PathwayData.put("data/reading_writing/units/L01U2.json",{"strand":"reading_writing","level":1,"cefr":"A1a","unit":2,"theme":"My Family and Home","essential_question":"What makes a home a happy place?","schema_version":"1.0","core_words":["mother","father","brother","sister","grandmother","grandfather","baby","house","room","kitchen","door","window","garden","help"],"recycled_words":["name","happy","big","small","like","friend","school","hand","eye","special"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L01-U2-LS1","title":"Word Power: My Family and Home","lesson_type":"vocabulary","objectives":["read and say 14 family and home words and 2 Tier 2 words (busy, ready)","sort naming words into people and places","use family and home words in short sentences about their own home"],"objectives_ar":["قراءة ونطق 14 كلمة عن الأسرة والمنزل وكلمتين أكاديميتين (busy, ready).","تصنيف كلمات التسمية إلى أشخاص وأماكن.","استخدام كلمات الأسرة والمنزل في جمل قصيرة عن منزلهم."],"success_criteria":["I can read and say the family and home words.","I can sort naming words into people and places.","I can say and write a sentence about my family or home."],"success_criteria_ar":["أستطيع قراءة كلمات الأسرة والمنزل ونطقها.","أستطيع تصنيف كلمات التسمية إلى أشخاص وأماكن.","أستطيع قول جملة وكتابتها عن أسرتي أو منزلي."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"mother","pos":"noun","ipa":"/ˈmʌðər/","definition":"a woman who has a child","arabic":"أم","example":"My mother reads to me.","image_id":"IMG-RW-L01-U2-LS1-V01","audio_id":"AUD-RW-L01-U2-LS1-V01","tier":"core"},{"word":"father","pos":"noun","ipa":"/ˈfɑðər/","definition":"a man who has a child","arabic":"أب","example":"My father drives a car.","image_id":"IMG-RW-L01-U2-LS1-V02","audio_id":"AUD-RW-L01-U2-LS1-V02","tier":"core"},{"word":"brother","pos":"noun","ipa":"/ˈbrʌðər/","definition":"a boy who has the same mother and father as you","arabic":"أخ","example":"My brother is ten.","image_id":"IMG-RW-L01-U2-LS1-V03","audio_id":"AUD-RW-L01-U2-LS1-V03","tier":"core"},{"word":"sister","pos":"noun","ipa":"/ˈsɪstər/","definition":"a girl who has the same mother and father as you","arabic":"أخت","example":"My sister likes cats.","image_id":"IMG-RW-L01-U2-LS1-V04","audio_id":"AUD-RW-L01-U2-LS1-V04","tier":"core"},{"word":"grandmother","pos":"noun","ipa":"/ˈɡrænˌmʌðər/","definition":"the mother of your mother or father","arabic":"جدة","example":"My grandmother makes coffee.","image_id":"IMG-RW-L01-U2-LS1-V05","audio_id":"AUD-RW-L01-U2-LS1-V05","tier":"core"},{"word":"grandfather","pos":"noun","ipa":"/ˈɡrænˌfɑðər/","definition":"the father of your mother or father","arabic":"جد","example":"Grandfather tells good stories.","image_id":"IMG-RW-L01-U2-LS1-V06","audio_id":"AUD-RW-L01-U2-LS1-V06","tier":"core"},{"word":"baby","pos":"noun","ipa":"/ˈbeɪbi/","definition":"a very young child","arabic":"طفل رضيع","example":"The baby is sleeping.","image_id":"IMG-RW-L01-U2-LS1-V07","audio_id":"AUD-RW-L01-U2-LS1-V07","tier":"core"},{"word":"house","pos":"noun","ipa":"/haʊs/","definition":"a building where a family lives","arabic":"منزل / بيت","example":"Our house has a green door.","image_id":"IMG-RW-L01-U2-LS1-V08","audio_id":"AUD-RW-L01-U2-LS1-V08","tier":"core"},{"word":"room","pos":"noun","ipa":"/rum/","definition":"a part of a house with walls and a door","arabic":"غرفة","example":"This room is big.","image_id":"IMG-RW-L01-U2-LS1-V09","audio_id":"AUD-RW-L01-U2-LS1-V09","tier":"core"},{"word":"kitchen","pos":"noun","ipa":"/ˈkɪtʃən/","definition":"the room where we cook food","arabic":"مطبخ","example":"The kitchen is clean.","image_id":"IMG-RW-L01-U2-LS1-V10","audio_id":"AUD-RW-L01-U2-LS1-V10","tier":"core"},{"word":"door","pos":"noun","ipa":"/dɔr/","definition":"you open it to go in or out of a room","arabic":"باب","example":"Close the door, please.","image_id":"IMG-RW-L01-U2-LS1-V11","audio_id":"AUD-RW-L01-U2-LS1-V11","tier":"core"},{"word":"window","pos":"noun","ipa":"/ˈwɪndoʊ/","definition":"glass in a wall; you look out of it","arabic":"نافذة","example":"I look out of the window.","image_id":"IMG-RW-L01-U2-LS1-V12","audio_id":"AUD-RW-L01-U2-LS1-V12","tier":"core"},{"word":"garden","pos":"noun","ipa":"/ˈɡɑrdən/","definition":"a place near a house with plants and flowers","arabic":"حديقة","example":"We play in the garden.","image_id":"IMG-RW-L01-U2-LS1-V13","audio_id":"AUD-RW-L01-U2-LS1-V13","tier":"core"},{"word":"help","pos":"verb","ipa":"/hɛlp/","definition":"to make work easier for someone","arabic":"يساعد","example":"I help my father wash the car.","image_id":"IMG-RW-L01-U2-LS1-V14","audio_id":"AUD-RW-L01-U2-LS1-V14","tier":"core"},{"word":"busy","pos":"adjective","ipa":"/ˈbɪzi/","definition":"doing many things; not free","arabic":"مشغول","example":"Mother is busy now.","image_id":"IMG-RW-L01-U2-LS1-V15","audio_id":"AUD-RW-L01-U2-LS1-V15","tier":"tier2"},{"word":"ready","pos":"adjective","ipa":"/ˈrɛdi/","definition":"prepared; all done and ready to start","arabic":"جاهز","example":"Dinner is ready.","image_id":"IMG-RW-L01-U2-LS1-V16","audio_id":"AUD-RW-L01-U2-LS1-V16","tier":"tier2"}],"explanation":{"text":"A **naming word** is the name of a person, a place or a thing. (Later you will call it a **noun**.)\n\nSome naming words are **people**: mother, father, baby. Some naming words are **places**: house, kitchen, garden.\n\nAsk: **Is it a person?** Is it a **place**? Then put it in the right group.","examples":["**mother** → a person","**brother** → a person","**grandfather** → a person","**baby** → a person","**kitchen** → a place","**garden** → a place","**house** → a place","**room** → a place","**door** and **window** → things in a house"],"common_errors":["✗ my brother she is ten. → ✓ My brother is ten. (Do not add **he/she** after the naming word.)","✗ I have two sister. → ✓ I have two sisters. (For more than one, add **-s**.)","✗ This is the house of my grandmother. → ✓ This is my grandmother's house. (English often uses **'s**.)","✗ The kitchin is big. → ✓ The kitchen is big. (Spelling: kitch**e**n.)","✗ I open the window to see the street. (said as \"vindow\") → ✓ window /ˈwɪndoʊ/ (Say /w/ with round lips, not /v/.)","✗ My father he is tall. → ✓ My father is tall. (One subject is enough.)","✗ the garden is in the house. → ✓ The garden is next to the house. (A garden is usually outside.)"],"arabic":"كلمة التسمية هي اسم لشخص أو مكان أو شيء، وستتعلم لاحقًا أن اسمها noun.\n\nبعض كلمات التسمية أشخاص مثل: mother, father, baby، وبعضها أماكن مثل: house, kitchen, garden.\n\nاسأل نفسك: هل هي شخص؟ هل هي مكان؟ ثم ضعها في المجموعة الصحيحة.\n\nانتبه: لا نقول My father he is tall، بل نقول My father is tall."},"video":{"script":[{"time":"00:00–00:15","narration":"Welcome to Noura's house! Let's meet her family.","on_screen":"My Family and Home","visual":"The front door of a Saudi house opens; Noura waves from inside."},{"time":"00:15–00:50","narration":"This is my mother. This is my father. This is my brother, Faris. This is my baby sister, Dana.","on_screen":"mother · father · brother · sister · baby","visual":"Each family member steps forward and a label slides in under them."},{"time":"00:50–01:10","narration":"And this is my grandmother, and this is my grandfather.","on_screen":"grandmother · grandfather","visual":"Grandmother pours coffee; Grandfather waves from the garden."},{"time":"01:10–01:40","narration":"Now the places! The kitchen, my room, the garden. Look at the door and the window.","on_screen":"kitchen · room · garden · door · window","visual":"The camera moves through the house; each place glows as it is named."},{"time":"01:40–02:10","narration":"Naming words can be people or places. Mother – person! Kitchen – place!","on_screen":"People 👪  |  Places 🏠","visual":"Word cards fly into two baskets labelled with a family icon and a house icon."},{"time":"02:10–02:30","narration":"Is it a person? Is it a place? You can sort them too!","on_screen":"Person or place?","visual":"Saqr juggles word cards and drops them into the right baskets."}],"captions_ar":["مرحبًا بكم في منزل نورة! لنتعرف على أسرتها.","هذه أمي، وهذا أبي، وهذا أخي فارس، وهذه أختي الصغيرة دانة.","وهذه جدتي، وهذا جدي.","والآن الأماكن: المطبخ، غرفتي، الحديقة. انظروا إلى الباب والنافذة.","كلمات التسمية قد تكون أشخاصًا أو أماكن: الأم شخص، والمطبخ مكان!","هل هي شخص؟ هل هي مكان؟ يمكنك أن تصنفها أيضًا!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Noura: friendly 9-year-old girl. Short pauses for repetition."},"texts":[],"activities":[{"id":"RW-L01-U2-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read and choose the correct word.","instructions_ar":"اقرأ واختر الكلمة الصحيحة.","items":[{"q":"We cook food in the ___.","answer":"kitchen","explanation":"The kitchen is where we cook.","explanation_ar":"المطبخ مكان الطبخ.","options":["kitchen","garden","window","baby"],"dok":1,"skill":"word meaning","stage":"controlled"},{"q":"The mother of my father is my ___.","answer":"grandmother","explanation":"Your parent's mother is your grandmother.","explanation_ar":"أم أبيك هي جدتك.","options":["grandmother","sister","baby","brother"],"dok":1,"skill":"word meaning","stage":"controlled"},{"q":"You open a ___ to go into a room.","answer":"door","explanation":"We go in and out through a door.","explanation_ar":"ندخل ونخرج من الباب.","options":["garden","door","baby","father"],"dok":1,"skill":"word meaning","stage":"controlled"},{"q":"A very young child is a ___.","answer":"baby","explanation":"A baby is a very young child.","explanation_ar":"الرضيع طفل صغير جدًا.","options":["grandfather","house","kitchen","baby"],"dok":1,"skill":"word meaning","stage":"controlled"},{"q":"Plants and flowers grow in the ___.","answer":"garden","explanation":"Plants grow in a garden.","explanation_ar":"النباتات تنمو في الحديقة.","options":["kitchen","door","garden","room"],"dok":1,"skill":"word meaning","stage":"controlled"},{"q":"A boy with the same mother and father as you is your ___.","answer":"brother","explanation":"That boy is your brother.","explanation_ar":"هو أخوك.","options":["sister","grandmother","mother","brother"],"dok":1,"skill":"word meaning","stage":"controlled"}]},{"id":"RW-L01-U2-LS1-A2","type":"gap_fill","stage":"guided","instructions":"Guided practice: Use the word bank to complete each sentence.","instructions_ar":"استخدم بنك الكلمات لإكمال الجمل.","items":[{"q":"I look out of the ________ and see the street.","answer":"window","explanation":"We look out of a window.","explanation_ar":"ننظر من النافذة.","stage":"guided"},{"q":"Our ________ has three rooms and a garden.","answer":"house","explanation":"A family lives in a house.","explanation_ar":"الأسرة تسكن في منزل.","stage":"guided"},{"q":"Mother is ________. She cooks, cleans and reads.","answer":"busy","explanation":"Busy means doing many things.","explanation_ar":"busy تعني مشغولة.","stage":"guided"},{"q":"I ________ my grandmother carry the bags.","answer":"help","explanation":"Help means to make work easier for someone.","explanation_ar":"help تعني يساعد.","stage":"guided"},{"q":"My ________ is ten. He likes football.","answer":"brother","explanation":"*He* tells us it is a boy.","explanation_ar":"كلمة He تدل على ولد.","stage":"guided"},{"q":"Lunch is ________. Come and eat!","answer":"ready","explanation":"Ready means all done and prepared.","explanation_ar":"ready تعني جاهز.","stage":"guided"}]},{"id":"RW-L01-U2-LS1-A3","type":"open","stage":"freer","instructions":"Freer practice: Sort the words. Write each word in the People box or the Places box.","instructions_ar":"صنّف الكلمات واكتب كل كلمة في مربع الأشخاص أو الأماكن.","items":[{"q":"father, kitchen, sister – write the PEOPLE words.","answer":"father, sister","explanation":"Father and sister are people.","explanation_ar":"الأب والأخت أشخاص.","dok":1,"skill":"sorting","stage":"freer"},{"q":"garden, baby, room – write the PLACES words.","answer":"garden, room","explanation":"Garden and room are places.","explanation_ar":"الحديقة والغرفة أماكن.","dok":1,"skill":"sorting","stage":"freer"},{"q":"Write two more PEOPLE words from this lesson.","answer":"grandfather, mother","explanation":"Any two family words.","explanation_ar":"أي كلمتين للأسرة.","dok":1,"skill":"sorting","stage":"freer"},{"q":"Write one more PLACE word you know.","answer":"school","explanation":"Any place word.","explanation_ar":"أي كلمة مكان.","dok":2,"skill":"sorting","stage":"freer"}]},{"id":"RW-L01-U2-LS1-A4","type":"open","stage":"production","instructions":"Writing: Write about YOUR home. Use the new words.","instructions_ar":"اكتب عن منزلك باستخدام الكلمات الجديدة.","items":[{"q":"Who is in your family? Write two people.","answer":"My mother and my brother are in my family.","explanation":"Two family words.","explanation_ar":"كلمتان للأسرة.","dok":1,"skill":"personal writing","stage":"production"},{"q":"Which room do you like? Write: I like the ___.","answer":"I like the kitchen.","explanation":"A room word.","explanation_ar":"كلمة غرفة.","dok":1,"skill":"personal writing","stage":"production"},{"q":"Who helps you at home? Write one sentence.","answer":"My sister helps me.","explanation":"A person + helps me.","explanation_ar":"شخص + helps me.","dok":2,"skill":"personal writing","stage":"production"},{"q":"Draw your house. Label the door, a window and the garden.","answer":"door, window, garden","explanation":"Three correct labels.","explanation_ar":"ثلاث بطاقات صحيحة.","dok":1,"skill":"labelling","stage":"production"}]}],"game":{"name":"Family Basket Toss","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Sort-and-swipe: a word card appears in the middle; swipe it left into the People house or right into the Places house. Correct = the card turns into a picture; wrong = a gentle buzz and a hint picture. 20 words, 60 seconds.","Make two teams. Each player gets one word card.","A player reads the card aloud and says \"person\" or \"place\".","If correct, the player drops the card in the right basket and throws the ball at the target circle on the board for a bonus point.","If wrong, the card goes back to the pile.","The team with more correct cards wins."],"data":[]},"exit_quiz":[{"q":"Which word is a person?","answer":"sister","explanation":"A sister is a person.","explanation_ar":"الأخت شخص.","options":["kitchen","garden","sister","window"],"dok":1,"skill":"naming words"},{"q":"Which word is a place?","answer":"kitchen","explanation":"A kitchen is a place.","explanation_ar":"المطبخ مكان.","options":["baby","father","kitchen","grandmother"],"dok":1,"skill":"naming words"},{"q":"The father of my mother is my ___.","answer":"grandfather","explanation":"Your parent's father is your grandfather.","explanation_ar":"أبو أمك هو جدك.","options":["brother","grandfather","baby","father"],"dok":1,"skill":"vocabulary"},{"q":"We sleep in a ___.","answer":"room","explanation":"We sleep in a bedroom.","explanation_ar":"ننام في غرفة.","options":["room","garden","window","door"],"dok":1,"skill":"vocabulary"},{"q":"Mother says, \"Dinner is ___!\"","answer":"ready","explanation":"Ready means prepared to eat.","explanation_ar":"ready تعني جاهز.","options":["busy","small","window","ready"],"dok":1,"skill":"vocabulary"},{"q":"Which group has only people?","answer":"mother, baby, brother","explanation":"All three are people.","explanation_ar":"الكلمات الثلاث أشخاص.","options":["mother, baby, brother","house, room, door","kitchen, mother, garden","window, sister, room"],"dok":2,"skill":"sorting"},{"q":"Which group has only places?","answer":"house, kitchen, garden","explanation":"All three are places.","explanation_ar":"الكلمات الثلاث أماكن.","options":["father, room, baby","sister, garden, door","house, kitchen, garden","grandmother, kitchen, baby"],"dok":2,"skill":"sorting"},{"q":"Father washes the car, cooks and cleans. He is ___.","answer":"busy","explanation":"Doing many things means busy.","explanation_ar":"يقوم بأشياء كثيرة فهو مشغول.","options":["ready","small","a baby","busy"],"dok":2,"skill":"vocabulary in context"},{"q":"Which word is a thing in a house, not a person or a place?","answer":"window","explanation":"A window is a thing.","explanation_ar":"النافذة شيء.","options":["sister","window","garden","kitchen"],"dok":2,"skill":"naming words"},{"q":"Dana is very young. She cannot walk yet. Dana is a ___.","answer":"baby","explanation":"A child who cannot walk yet is a baby.","explanation_ar":"الطفلة التي لا تمشي بعد رضيعة.","options":["grandmother","baby","father","brother"],"dok":3,"skill":"inference"}],"images":[{"id":"IMG-RW-L01-U2-LS1-V01","prompt":"Picture for the word 'mother': a mother in a light-blue abaya reading a book to her child"},{"id":"IMG-RW-L01-U2-LS1-V02","prompt":"Picture for the word 'father': a father in a white thobe holding his son's hand"},{"id":"IMG-RW-L01-U2-LS1-V03","prompt":"Picture for the word 'brother': two boys of different heights standing side by side, smiling"},{"id":"IMG-RW-L01-U2-LS1-V04","prompt":"Picture for the word 'sister': two girls holding hands, one older and one younger"},{"id":"IMG-RW-L01-U2-LS1-V05","prompt":"Picture for the word 'grandmother': a smiling grandmother in a dark abaya pouring Arabic coffee"},{"id":"IMG-RW-L01-U2-LS1-V06","prompt":"Picture for the word 'grandfather': Grandpa Saleh in a red shemagh telling a story to children"},{"id":"IMG-RW-L01-U2-LS1-V07","prompt":"Picture for the word 'baby': a baby sleeping in a small crib"},{"id":"IMG-RW-L01-U2-LS1-V08","prompt":"Picture for the word 'house': a two-story Saudi house with a green door and a palm tree"},{"id":"IMG-RW-L01-U2-LS1-V09","prompt":"Picture for the word 'room': a bright bedroom with a bed and a window"},{"id":"IMG-RW-L01-U2-LS1-V10","prompt":"Picture for the word 'kitchen': a kitchen with a stove, pots and a fridge"},{"id":"IMG-RW-L01-U2-LS1-V11","prompt":"Picture for the word 'door': a wooden door half open"},{"id":"IMG-RW-L01-U2-LS1-V12","prompt":"Picture for the word 'window': a window with a mashrabiya frame and blue sky outside"},{"id":"IMG-RW-L01-U2-LS1-V13","prompt":"Picture for the word 'garden': a small home garden with flowers and a palm tree"},{"id":"IMG-RW-L01-U2-LS1-V14","prompt":"Picture for the word 'help': a boy helping his father wash a car with a sponge"},{"id":"IMG-RW-L01-U2-LS1-V15","prompt":"Picture for the word 'busy': a mother doing many jobs at once, with small motion lines"},{"id":"IMG-RW-L01-U2-LS1-V16","prompt":"Picture for the word 'ready': a table with food set out and steam rising"},{"id":"IMG-RW-L01-U2-LS1-01","prompt":"Noura's family together in their living room."},{"id":"IMG-RW-L01-U2-LS1-02","prompt":"A house drawn open to show its rooms and garden."},{"id":"IMG-RW-L01-U2-LS1-03","prompt":"Two baskets, one for people and one for places."}],"audio":[{"id":"AUD-RW-L01-U2-LS1-V01","script":"mother. My mother reads to me."},{"id":"AUD-RW-L01-U2-LS1-V02","script":"father. My father drives a car."},{"id":"AUD-RW-L01-U2-LS1-V03","script":"brother. My brother is ten."},{"id":"AUD-RW-L01-U2-LS1-V04","script":"sister. My sister likes cats."},{"id":"AUD-RW-L01-U2-LS1-V05","script":"grandmother. My grandmother makes coffee."},{"id":"AUD-RW-L01-U2-LS1-V06","script":"grandfather. Grandfather tells good stories."},{"id":"AUD-RW-L01-U2-LS1-V07","script":"baby. The baby is sleeping."},{"id":"AUD-RW-L01-U2-LS1-V08","script":"house. Our house has a green door."},{"id":"AUD-RW-L01-U2-LS1-V09","script":"room. This room is big."},{"id":"AUD-RW-L01-U2-LS1-V10","script":"kitchen. The kitchen is clean."},{"id":"AUD-RW-L01-U2-LS1-V11","script":"door. Close the door, please."},{"id":"AUD-RW-L01-U2-LS1-V12","script":"window. I look out of the window."},{"id":"AUD-RW-L01-U2-LS1-V13","script":"garden. We play in the garden."},{"id":"AUD-RW-L01-U2-LS1-V14","script":"help. I help my father wash the car."},{"id":"AUD-RW-L01-U2-LS1-V15","script":"busy. Mother is busy now."},{"id":"AUD-RW-L01-U2-LS1-V16","script":"ready. Dinner is ready."},{"id":"AUD-RW-L01-U2-LS1-VID","script":"Welcome to Noura's house! Let's meet her family. This is my mother. This is my father. This is my brother, Faris. This is my baby sister, Dana. And this is my grandmother, and this is my grandfather. Now the places! The kitchen, my room, the garden. Look at the door and the window. Naming words can be people or places. Mother – person! Kitchen – place! Is it a person? Is it a place? You can sort them too!"}]},{"id":"RW-L01-U2-LS2","title":"A Busy Morning at Noura's House","lesson_type":"close_reading","objectives":["take a picture walk and predict what a story is about before reading","read a short story (about 85 words) and answer who, what and where questions with evidence","check their prediction and say why the home is a happy place"],"objectives_ar":["القيام بجولة في الصور وتوقّع موضوع القصة قبل قراءتها.","قراءة قصة قصيرة (نحو 85 كلمة) والإجابة عن أسئلة من وماذا وأين مع الدليل.","التحقق من التوقع وقول لماذا كان المنزل مكانًا سعيدًا."],"success_criteria":["I can look at the pictures and predict.","I can read the story and find answers in it.","I can check my prediction."],"success_criteria_ar":["أستطيع النظر إلى الصور والتوقّع.","أستطيع قراءة القصة وإيجاد الإجابات فيها.","أستطيع التحقق من توقّعي."],"map_area":"Literary Text: Key Ideas and Details","vocabulary":[{"word":"morning","pos":"noun","ipa":"/ˈmɔrnɪŋ/","definition":"the first part of the day","arabic":"الصباح","example":"I drink milk in the morning.","image_id":"IMG-RW-L01-U2-LS2-V01","audio_id":"AUD-RW-L01-U2-LS2-V01","tier":"core"},{"word":"breakfast","pos":"noun","ipa":"/ˈbrɛkfəst/","definition":"the first meal of the day","arabic":"الإفطار (وجبة الصباح)","example":"We eat breakfast at seven.","image_id":"IMG-RW-L01-U2-LS2-V02","audio_id":"AUD-RW-L01-U2-LS2-V02","tier":"core"},{"word":"plate","pos":"noun","ipa":"/pleɪt/","definition":"a flat dish for food","arabic":"طبق / صحن","example":"Put the bread on the plate.","image_id":"IMG-RW-L01-U2-LS2-V03","audio_id":"AUD-RW-L01-U2-LS2-V03","tier":"core"},{"word":"table","pos":"noun","ipa":"/ˈteɪbəl/","definition":"furniture with a flat top and legs","arabic":"طاولة","example":"The book is on the table.","image_id":"IMG-RW-L01-U2-LS2-V04","audio_id":"AUD-RW-L01-U2-LS2-V04","tier":"core"},{"word":"open","pos":"verb","ipa":"/ˈoʊpən/","definition":"to move something so it is not closed","arabic":"يفتح","example":"Please open your book.","image_id":"IMG-RW-L01-U2-LS2-V05","audio_id":"AUD-RW-L01-U2-LS2-V05","tier":"core"},{"word":"look for","pos":"verb","ipa":"/lʊk fɔr/","definition":"to try to find","arabic":"يبحث عن","example":"I look for my pen.","image_id":"IMG-RW-L01-U2-LS2-V06","audio_id":"AUD-RW-L01-U2-LS2-V06","tier":"core"},{"word":"everyone","pos":"pronoun","ipa":"/ˈɛvriˌwʌn/","definition":"all the people","arabic":"الجميع","example":"Everyone is here.","image_id":"IMG-RW-L01-U2-LS2-V07","audio_id":"AUD-RW-L01-U2-LS2-V07","tier":"core"}],"explanation":{"text":"Before you read, take a **picture walk**. Look at the title and the pictures.\n\nThen **predict**: say what you think the story is about. Use: *I think the story is about…*\n\nRead the story. Then **check**: Was your prediction right? It is OK to change your idea!","examples":["Title: *A Busy Morning at Noura's House*. → I think the story is about a morning at home.","Picture: a mother cooking eggs. → I think Mother makes breakfast.","Picture: a boy looking under a chair. → I think he looks for something.","Picture: a man with water near plants. → I think Grandfather waters the garden.","Picture: a family at a table. → I think they eat together.","Check: \"Mother is in the kitchen. She makes eggs and bread.\" → My prediction is right!","Check: The boy looks for his school bag. → I predicted a toy, so I change my idea.","Right There: *Who opens the window?* → Father.","Think: *Why is the house busy?* → Everyone is doing a job in the morning."],"common_errors":["✗ I think the story about a family. → ✓ I think the story is about a family. (Do not forget **is**.)","✗ Mother make eggs. → ✓ Mother makes eggs. (With he/she or one person, add **-s**.)","✗ Faris look for his bag. → ✓ Faris looks for his bag. (One person → **looks**.)","✗ They eat in the breakfast. → ✓ They eat breakfast. (We say **eat breakfast** without *in the*.)","✗ Grandfather water the garden. → ✓ Grandfather waters the garden. (One person → **waters**.)","✗ My prediction is wrong, so I am bad reader. → ✓ My prediction changed. Good readers change their ideas. (Changing a prediction is a reading skill!)"],"arabic":"قبل القراءة قم بجولة في الصور: انظر إلى العنوان والصور.\n\nثم توقَّع: قل ما تظن أن القصة تتحدث عنه باستخدام: I think the story is about…\n\nاقرأ القصة ثم تحقَّق: هل كان توقعك صحيحًا؟ لا بأس أن تغيّر رأيك، فالقارئ الجيد يغيّر توقعه.\n\nانتبه: نقول Mother makes وFaris looks بإضافة s مع الشخص الواحد."},"video":{"script":[{"time":"00:00–00:20","narration":"Let's take a picture walk! Look at the title and the pictures.","on_screen":"Picture walk 👀","visual":"Saqr walks along a path of picture frames from the story."},{"time":"00:20–00:45","narration":"What do you think? I think the story is about a busy morning at home.","on_screen":"I think the story is about…","visual":"A thought bubble appears with a sun, a house and a clock."},{"time":"00:45–01:40","narration":"It is morning. Noura's house is busy! Mother is in the kitchen…","on_screen":"(story text, sentence by sentence)","visual":"Each sentence is highlighted; the matching picture zooms in: kitchen, window, Faris at the door, Dana and Grandmother, Grandfather in the garden, the breakfast table."},{"time":"01:40–02:10","narration":"Now check! Was your prediction right? Yes – it is a busy morning!","on_screen":"Check ✔","visual":"A big tick stamps the thought bubble; one wrong guess (a toy) changes to a school bag."},{"time":"02:10–02:30","narration":"Why is Noura's home a happy place? Everyone helps, and they eat together.","on_screen":"Everyone helps 🤝","visual":"The family smiles at the table; small hearts float up."},{"time":"02:30–02:40","narration":"Look, predict, read, check!","on_screen":"Look · Predict · Read · Check","visual":"Four icons light up in a row."}],"captions_ar":["لنقم بجولة في الصور! انظروا إلى العنوان والصور.","ماذا تتوقعون؟ أتوقع أن القصة عن صباح مزدحم في المنزل.","إنه الصباح. منزل نورة مشغول! الأم في المطبخ…","تحققوا الآن! هل كان توقعكم صحيحًا؟ نعم، إنه صباح مزدحم!","لماذا منزل نورة مكان سعيد؟ لأن الجميع يساعد ويأكلون معًا.","انظر، توقَّع، اقرأ، تحقَّق!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Story reader: Noura's voice, cheerful. Pause 1 second after each sentence of the story."},"texts":[{"type":"reading","title":"A Busy Morning at Noura's House","body":"It is morning. Noura's house is busy!\n\nMother is in the kitchen. She makes eggs and bread. Father opens the big window, and the sun comes in.\n\nNoura's brother, Faris, looks for his school bag by the door. Her baby sister, Dana, is small. She sits with Grandmother in her room. Grandfather waters the garden.\n\nNoura helps her mother. She puts the plates on the table.\n\n\"Breakfast is ready!\" says Mother. Everyone sits together. They eat and smile. Noura's home is a happy place.","word_count":84,"audio_id":"AUD-RW-L01-U2-LS2-T1","id":"TXT-RW-L01-U2-LS2-1","genre":"narrative","role":"main","difficulty":"BR–200L","glossary":[{"word":"waters","definition":"gives water to plants","arabic":"يسقي"},{"word":"by the door","definition":"next to the door","arabic":"بجانب الباب"}]}],"activities":[{"id":"RW-L01-U2-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the story. Choose the answer.","instructions_ar":"اقرأ القصة واختر الإجابة.","items":[{"q":"Where is Mother?","answer":"in the kitchen","explanation":"Text: Mother is in the kitchen.","explanation_ar":"الأم في المطبخ.","options":["in the garden","in the kitchen","at school","in the car"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"What does Mother make?","answer":"eggs and bread","explanation":"Text: She makes eggs and bread.","explanation_ar":"تصنع البيض والخبز.","options":["eggs and bread","rice and chicken","dates and milk","a cake"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Who opens the big window?","answer":"Father","explanation":"Text: Father opens the big window.","explanation_ar":"الأب يفتح النافذة.","options":["Faris","Father","Grandmother","Dana"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"What does Faris look for?","answer":"his school bag","explanation":"Text: looks for his school bag.","explanation_ar":"يبحث عن حقيبته المدرسية.","options":["his ball","a plate","his school bag","the baby"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Who is Dana with?","answer":"Grandmother","explanation":"Text: She sits with Grandmother.","explanation_ar":"دانة مع جدتها.","options":["Grandmother","Grandfather","Father","Faris"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"What does Grandfather do?","answer":"He waters the garden.","explanation":"Text: Grandfather waters the garden.","explanation_ar":"الجد يسقي الحديقة.","options":["He makes bread.","He opens the door.","He sits in his room.","He waters the garden."],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L01-U2-LS2-A2","type":"true_false","stage":"guided","instructions":"Guided practice: True or false? Circle one.","instructions_ar":"صح أم خطأ؟ ضع دائرة.","items":[{"q":"The story happens in the morning.","answer":"true","explanation":"Text: It is morning.","explanation_ar":"تحدث القصة في الصباح.","options":["true","false"],"stage":"guided"},{"q":"Dana is a big girl.","answer":"false","explanation":"Text: Dana is small; she is a baby.","explanation_ar":"دانة رضيعة صغيرة.","options":["true","false"],"stage":"guided"},{"q":"Faris's bag is by the window.","answer":"false","explanation":"Text: by the door.","explanation_ar":"الحقيبة بجانب الباب.","options":["true","false"],"stage":"guided"},{"q":"Noura puts the plates on the table.","answer":"true","explanation":"Text: She puts the plates on the table.","explanation_ar":"نورة تضع الأطباق على الطاولة.","options":["true","false"],"stage":"guided"},{"q":"The family eats alone, one by one.","answer":"false","explanation":"Text: Everyone sits together.","explanation_ar":"يجلسون جميعًا معًا.","options":["true","false"],"stage":"guided"},{"q":"The sun comes in through the window.","answer":"true","explanation":"Text: the sun comes in.","explanation_ar":"تدخل الشمس من النافذة.","options":["true","false"],"stage":"guided"}]},{"id":"RW-L01-U2-LS2-A3","type":"highlight","stage":"freer","instructions":"Find the evidence: Underline the evidence or choose the best answer.","instructions_ar":"ضع خطًا تحت الدليل أو اختر أفضل إجابة.","items":[{"q":"Underline the sentence that shows how Noura helps.","answer":"She puts the plates on the table.","explanation":"This sentence shows her job.","explanation_ar":"هذه الجملة تبيّن كيف تساعد.","evidence":"She puts the plates on the table.","text_id":"TXT-RW-L01-U2-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["It is morning.","Noura's house is busy!","Mother is in the kitchen.","She makes eggs and bread.","Father opens the big window, and the sun comes in.","Noura's brother, Faris, looks for his school bag by the door.","Her baby sister, Dana, is small.","She sits with Grandmother in her room.","Grandfather waters the garden.","Noura helps her mother.","She puts the plates on the table.","\"Breakfast is ready!\" says Mother.","Everyone sits together.","They eat and smile.","Noura's home is a happy place."]},{"q":"Underline the words Mother says.","answer":"\"Breakfast is ready!\"","explanation":"Words in quotation marks are what she says.","explanation_ar":"الكلمات بين علامتي التنصيص هي كلامها.","evidence":"\"Breakfast is ready!\"","text_id":"TXT-RW-L01-U2-LS2-1","dok":1,"skill":"evidence","stage":"freer","sentences":["It is morning.","Noura's house is busy!","Mother is in the kitchen.","She makes eggs and bread.","Father opens the big window, and the sun comes in.","Noura's brother, Faris, looks for his school bag by the door.","Her baby sister, Dana, is small.","She sits with Grandmother in her room.","Grandfather waters the garden.","Noura helps her mother.","She puts the plates on the table.","\"Breakfast is ready!\" says Mother.","Everyone sits together.","They eat and smile.","Noura's home is a happy place."]},{"q":"Why is the house busy?","answer":"Everyone has a job in the morning.","explanation":"Many people do many things.","explanation_ar":"الجميع لديه عمل في الصباح.","options":["The house is very small.","Nobody is at home.","Everyone has a job in the morning.","It is night."],"dok":2,"skill":"inference","stage":"freer"},{"q":"How does the family feel at breakfast?","answer":"happy","explanation":"Text: They eat and smile.","explanation_ar":"يبتسمون فهم سعداء.","options":["angry","tired","scared","happy"],"dok":2,"skill":"inference","stage":"freer"}]},{"id":"RW-L01-U2-LS2-A4","type":"open","stage":"production","instructions":"Writing: Me questions. Write your answers.","instructions_ar":"أسئلة عنك: اكتب إجاباتك.","items":[{"q":"What was your prediction? Was it right?","answer":"I think the story is about a family. Yes, it was right.","explanation":"Prediction + check.","explanation_ar":"التوقع والتحقق منه.","dok":2,"skill":"predict and check","stage":"production"},{"q":"How do you help at home in the morning?","answer":"I make my bed.","explanation":"A true sentence with a job.","explanation_ar":"جملة صحيحة عن عمل تقوم به.","dok":2,"skill":"connect","stage":"production"},{"q":"Who is busy in your house in the morning?","answer":"My mother is busy.","explanation":"A person + is busy.","explanation_ar":"شخص + is busy.","dok":1,"skill":"connect","stage":"production"},{"q":"Is Noura's home a happy place? Why?","answer":"Yes. Everyone helps and they eat together.","explanation":"Yes + a reason from the story.","explanation_ar":"نعم مع سبب من القصة.","dok":3,"skill":"evaluate","stage":"production"}]},{"id":"RW-L01-U2-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"A Busy Morning at Noura's House\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “A Busy Morning at Noura's House”.","answer":"84 words","title":"A Busy Morning at Noura's House","body":"It is morning. Noura's house is busy!\n\nMother is in the kitchen. She makes eggs and bread. Father opens the big window, and the sun comes in.\n\nNoura's brother, Faris, looks for his school bag by the door. Her baby sister, Dana, is small. She sits with Grandmother in her room. Grandfather waters the garden.\n\nNoura helps her mother. She puts the plates on the table.\n\n\"Breakfast is ready!\" says Mother. Everyone sits together. They eat and smile. Noura's home is a happy place.","words":84,"limit":141}],"time_limit_sec":141}],"game":{"name":"Who Am I? Story Riddles","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Riddle tap: a three-clue riddle appears one clue at a time; the child taps the right character face. Faster answers (after fewer clues) earn more stars.","The teacher reads clue 1 of a riddle (e.g., \"I am in the kitchen.\").","Teams may ring the bell and guess; a correct guess after clue 1 = 3 points.","If nobody guesses, read clue 2 (2 points), then clue 3 (1 point).","A wrong guess = that team cannot guess again for this riddle.","Play 6 riddles; the team with the most points wins."],"data":[]},"exit_quiz":[{"q":"What time of day is it in the story?","answer":"morning","explanation":"Text: It is morning.","explanation_ar":"إنه الصباح.","options":["morning","night","evening","afternoon"],"dok":1,"skill":"key details"},{"q":"Who is Faris?","answer":"Noura's brother","explanation":"Text: Noura's brother, Faris.","explanation_ar":"فارس أخو نورة.","options":["Noura's father","Noura's friend","Noura's brother","Noura's grandfather"],"dok":1,"skill":"key details: who"},{"q":"Where is Faris's school bag?","answer":"by the door","explanation":"Text: by the door.","explanation_ar":"بجانب الباب.","options":["on the table","in the garden","in the kitchen","by the door"],"dok":1,"skill":"key details: where"},{"q":"What does Noura put on the table?","answer":"the plates","explanation":"Text: She puts the plates on the table.","explanation_ar":"تضع الأطباق.","options":["the bread","the plates","her bag","the eggs"],"dok":1,"skill":"key details"},{"q":"Which words does Mother say?","answer":"\"Breakfast is ready!\"","explanation":"These are Mother's words in the story.","explanation_ar":"هذه كلمات الأم.","options":["\"Good night!\"","\"Where is my bag?\"","\"Open the door!\"","\"Breakfast is ready!\""],"dok":1,"skill":"key details"},{"q":"Before reading, a picture walk helps you ___.","answer":"predict what the story is about","explanation":"We look at pictures to predict.","explanation_ar":"جولة الصور تساعدنا على التوقع.","options":["predict what the story is about","write the story","count the words","find a new book"],"dok":1,"skill":"strategy"},{"q":"Which is a good prediction for the title *A Busy Morning at Noura's House*?","answer":"The family does many things before breakfast.","explanation":"The title says busy and morning.","explanation_ar":"العنوان يذكر صباحًا مزدحمًا.","options":["The family does many things before breakfast.","Noura goes to the moon.","A camel runs in the desert.","It is night and everyone sleeps."],"dok":2,"skill":"predict"},{"q":"*Grandfather waters the garden.* What does *waters* mean?","answer":"gives water to plants","explanation":"To water plants is to give them water.","explanation_ar":"يسقي النباتات.","options":["drinks water","swims in water","gives water to plants","makes tea"],"dok":2,"skill":"word in context"},{"q":"Why does everyone smile at the end?","answer":"They are happy together.","explanation":"Eating together makes them happy.","explanation_ar":"الاجتماع على الطعام يسعدهم.","options":["They are very tired.","They are happy together.","Faris cannot find his bag.","The food is cold."],"dok":2,"skill":"inference"},{"q":"What makes Noura's home a happy place?","answer":"Everyone helps and they eat together.","explanation":"The story shows helping and being together.","explanation_ar":"المساعدة والاجتماع يجعلان البيت سعيدًا.","options":["The house is very big.","Nobody talks.","Everyone helps and they eat together.","Father is not at home."],"dok":3,"skill":"theme"}],"images":[{"id":"IMG-RW-L01-U2-LS2-V01","prompt":"Picture for the word 'morning': a sunrise over houses and palm trees"},{"id":"IMG-RW-L01-U2-LS2-V02","prompt":"Picture for the word 'breakfast': a breakfast table with eggs, bread, cheese and tea"},{"id":"IMG-RW-L01-U2-LS2-V03","prompt":"Picture for the word 'plate': a white plate with bread on it"},{"id":"IMG-RW-L01-U2-LS2-V04","prompt":"Picture for the word 'table': a wooden dining table with four chairs"},{"id":"IMG-RW-L01-U2-LS2-V05","prompt":"Picture for the word 'open': a hand opening a window"},{"id":"IMG-RW-L01-U2-LS2-V06","prompt":"Picture for the word 'look for': a boy looking under a bed for his bag"},{"id":"IMG-RW-L01-U2-LS2-V07","prompt":"Picture for the word 'everyone': a whole family waving together"},{"id":"IMG-RW-L01-U2-LS2-01","prompt":"Mother cooks eggs while Father opens a sunny window."},{"id":"IMG-RW-L01-U2-LS2-02","prompt":"Faris looks for his bag, Grandmother holds the baby and Grandfather waters the garden."},{"id":"IMG-RW-L01-U2-LS2-03","prompt":"The family eats breakfast together and smiles."}],"audio":[{"id":"AUD-RW-L01-U2-LS2-V01","script":"morning. I drink milk in the morning."},{"id":"AUD-RW-L01-U2-LS2-V02","script":"breakfast. We eat breakfast at seven."},{"id":"AUD-RW-L01-U2-LS2-V03","script":"plate. Put the bread on the plate."},{"id":"AUD-RW-L01-U2-LS2-V04","script":"table. The book is on the table."},{"id":"AUD-RW-L01-U2-LS2-V05","script":"open. Please open your book."},{"id":"AUD-RW-L01-U2-LS2-V06","script":"look for. I look for my pen."},{"id":"AUD-RW-L01-U2-LS2-V07","script":"everyone. Everyone is here."},{"id":"AUD-RW-L01-U2-LS2-T1","script":"It is morning. Noura's house is busy! Mother is in the kitchen. She makes eggs and bread. Father opens the big window, and the sun comes in. Noura's brother, Faris, looks for his school bag by the door. Her baby sister, Dana, is small. She sits with Grandmother in her room. Grandfather waters the garden. Noura helps her mother. She puts the plates on the table. \"Breakfast is ready!\" says Mother. Everyone sits together. They eat and smile. Noura's home is a happy place."},{"id":"AUD-RW-L01-U2-LS2-VID","script":"Let's take a picture walk! Look at the title and the pictures. What do you think? I think the story is about a busy morning at home. It is morning. Noura's house is busy! Mother is in the kitchen… Now check! Was your prediction right? Yes – it is a busy morning! Why is Noura's home a happy place? Everyone helps, and they eat together. Look, predict, read, check!"}]},{"id":"RW-L01-U2-LS3","title":"Characters: who is in the story?: \"A Note from Grandma\"","lesson_type":"strategy_paired_text","objectives":["name the characters in a story and a note and say who the main character is","describe a character using what the character does, says and feels","find the parts of a short note: greeting, message, closing, name"],"objectives_ar":["تسمية الشخصيات في القصة والرسالة وتحديد الشخصية الرئيسية.","وصف الشخصية من خلال ما تفعله وتقوله وتشعر به.","إيجاد أجزاء الرسالة القصيرة: التحية، والرسالة، والخاتمة، والاسم."],"success_criteria":["I can name the characters.","I can say what a character does and feels.","I can find the parts of a note."],"success_criteria_ar":["أستطيع تسمية الشخصيات.","أستطيع قول ما تفعله الشخصية وما تشعر به.","أستطيع إيجاد أجزاء الرسالة."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"character","pos":"noun","ipa":"/ˈkɛrəktər/","definition":"a person or an animal in a story","arabic":"شخصية (في القصة)","example":"Noura is a character in the story.","image_id":"IMG-RW-L01-U2-LS3-V01","audio_id":"AUD-RW-L01-U2-LS3-V01","tier":"core"},{"word":"note","pos":"noun","ipa":"/noʊt/","definition":"a short letter","arabic":"رسالة قصيرة / ملاحظة","example":"Grandma writes a note.","image_id":"IMG-RW-L01-U2-LS3-V02","audio_id":"AUD-RW-L01-U2-LS3-V02","tier":"core"},{"word":"dear","pos":"adjective","ipa":"/dɪr/","definition":"a word to start a letter to someone","arabic":"عزيزي / عزيزتي","example":"Dear Omar, thank you for the ball.","image_id":"IMG-RW-L01-U2-LS3-V03","audio_id":"AUD-RW-L01-U2-LS3-V03","tier":"core"},{"word":"kind","pos":"adjective","ipa":"/kaɪnd/","definition":"nice and helpful to others","arabic":"لطيف / طيّب","example":"My teacher is kind.","image_id":"IMG-RW-L01-U2-LS3-V04","audio_id":"AUD-RW-L01-U2-LS3-V04","tier":"core"},{"word":"thank you","pos":"phrase","ipa":"/ˈθæŋk ju/","definition":"words we say when someone helps us or gives us something","arabic":"شكرًا لك","example":"Thank you for the gift.","image_id":"IMG-RW-L01-U2-LS3-V05","audio_id":"AUD-RW-L01-U2-LS3-V05","tier":"core"},{"word":"please","pos":"adverb","ipa":"/pliz/","definition":"a polite word when we ask for something","arabic":"من فضلك","example":"Please sit down.","image_id":"IMG-RW-L01-U2-LS3-V06","audio_id":"AUD-RW-L01-U2-LS3-V06","tier":"core"},{"word":"after","pos":"preposition","ipa":"/ˈæftər/","definition":"later than","arabic":"بعد","example":"We play after lunch.","image_id":"IMG-RW-L01-U2-LS3-V07","audio_id":"AUD-RW-L01-U2-LS3-V07","tier":"core"}],"explanation":{"text":"**Characters** are the people or animals in a story.\n\nThe **main character** is the most important one. The story is mostly about this character.\n\nWe learn about a character from what the character **does**, **says** and **feels**.\n\nA **note** is a short letter. It has a **greeting** (Dear Noura,), a **message**, a **closing** (With love,) and a **name** (Grandma).","examples":["Characters in the story: Noura, Mother, Father, Faris, Dana, Grandmother, Grandfather.","Main character: **Noura** – the title says \"Noura's House\" and she helps.","Noura **does**: she puts the plates on the table.","Mother **says**: \"Breakfast is ready!\"","The family **feels**: happy – they eat and smile.","Faris **does**: he looks for his school bag.","In the note, Grandma **says**: \"You are a kind girl.\"","In the note, Noura **does**: she plays with baby Dana.","Note parts: **Dear Noura,** (greeting) → message → **With love,** (closing) → **Grandma** (name)."],"common_errors":["✗ The character is the kitchen. → ✓ The kitchen is a place, not a character. (Characters are people or animals.)","✗ Noura she is the main character. → ✓ Noura is the main character. (One subject only.)","✗ Dear Noura. (with a period) → ✓ Dear Noura, (with a comma) (Put a **comma** after the greeting.)","✗ With love Grandma (on one line) → ✓ With love, / Grandma (two lines) (Put the name on its own line.)","✗ Grandma say thank you. → ✓ Grandma says thank you. (One person → **says**.)","✗ Noura is kind girl. → ✓ Noura is a kind girl. (Use **a** before kind girl.)"],"arabic":"الشخصيات هي الأشخاص أو الحيوانات في القصة، والشخصية الرئيسية هي أهم شخصية وتدور القصة حولها.\n\nنتعرّف على الشخصية مما تفعله وما تقوله وما تشعر به.\n\nالرسالة القصيرة (note) لها تحية مثل Dear Noura, ثم الرسالة، ثم خاتمة مثل With love, ثم اسم الكاتب.\n\nانتبه: نضع فاصلة بعد التحية Dear Noura, وليس نقطة."},"video":{"script":[{"time":"00:00–00:15","narration":"Who is in the story? The people in a story are the characters.","on_screen":"Characters 👪","visual":"Small figures of Noura's family pop out of an open book."},{"time":"00:15–00:45","narration":"Noura is the main character. The story is mostly about her.","on_screen":"Main character: Noura ⭐","visual":"A spotlight shines on Noura; the others step back a little."},{"time":"00:45–01:10","narration":"What does she do? She puts the plates on the table. How does she feel? Happy!","on_screen":"does · says · feels","visual":"Three bubbles around Noura fill with a plate icon, a speech bubble and a smiley face."},{"time":"01:10–01:45","narration":"Dear Noura, Thank you for your help today. You are a kind girl…","on_screen":"(the note)","visual":"Grandma writes the note at her desk; each line appears in handwriting style."},{"time":"01:45–02:05","narration":"A note has a greeting, a message, a closing and a name.","on_screen":"Dear… / message / With love, / name","visual":"Four colored brackets mark the four parts of the note."},{"time":"02:05–02:20","narration":"Find the characters. Find the parts. You can do it!","on_screen":"Find the characters!","visual":"Saqr holds a magnifying glass over the note and winks."}],"captions_ar":["مَن في القصة؟ الأشخاص في القصة هم الشخصيات.","نورة هي الشخصية الرئيسية؛ تدور القصة غالبًا حولها.","ماذا تفعل؟ تضع الأطباق على الطاولة. بماذا تشعر؟ بالسعادة!","عزيزتي نورة، شكرًا لمساعدتك اليوم. أنتِ بنت لطيفة…","للرسالة تحية ورسالة وخاتمة واسم.","ابحث عن الشخصيات وعن الأجزاء. تستطيع ذلك!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Grandma: gentle, warm older woman's voice reading the note slowly."},"texts":[{"type":"reading","title":"A Note from Grandma","body":"Dear Noura,\n\nThank you for your help today. You are a kind girl. You help Mother in the kitchen, and you play with baby Dana. Our home is happy with you in it.\n\nPlease come to my room after school. I have a new book for you!\n\nWith love,\n\nGrandma","word_count":50,"audio_id":"AUD-RW-L01-U2-LS3-T1","id":"TXT-RW-L01-U2-LS3-1","genre":"letter/email","role":"paired","difficulty":"BR–200L","glossary":[{"word":"With love,","definition":"a kind way to end a note to family","arabic":"مع حبي،"},{"word":"Grandma","definition":"a short, friendly word for grandmother","arabic":"جدتي (بلطف)"}]}],"activities":[{"id":"RW-L01-U2-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the answer about characters.","instructions_ar":"اختر الإجابة عن الشخصيات.","items":[{"q":"A character in a story is ___.","answer":"a person or an animal","explanation":"Characters are people or animals.","explanation_ar":"الشخصيات أشخاص أو حيوانات.","options":["a person or an animal","a place","a color","a number"],"dok":1,"skill":"characters","stage":"controlled"},{"q":"Who is the main character in *A Busy Morning at Noura's House*?","answer":"Noura","explanation":"The title and the story are mostly about Noura.","explanation_ar":"العنوان والقصة عن نورة.","options":["Faris","Noura","Grandfather","Dana"],"dok":1,"skill":"main character","stage":"controlled"},{"q":"Which one is NOT a character in the story?","answer":"the kitchen","explanation":"The kitchen is a place.","explanation_ar":"المطبخ مكان وليس شخصية.","options":["Mother","Faris","the kitchen","Dana"],"dok":1,"skill":"characters","stage":"controlled"},{"q":"Who writes the note?","answer":"Grandma","explanation":"The name at the end is Grandma.","explanation_ar":"الاسم في النهاية Grandma.","options":["Noura","Grandma","Mother","Faris"],"dok":1,"skill":"characters","text_id":"TXT-RW-L01-U2-LS3-1","stage":"controlled"},{"q":"Who is the note for?","answer":"Noura","explanation":"Greeting: Dear Noura,","explanation_ar":"التحية: Dear Noura.","options":["Dana","Father","Grandfather","Noura"],"dok":1,"skill":"characters","stage":"controlled"},{"q":"Who does Noura play with in the note?","answer":"baby Dana","explanation":"Text: you play with baby Dana.","explanation_ar":"تلعب مع دانة.","options":["Faris","Omar","Grandfather","baby Dana"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L01-U2-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Read the note again. Choose the answer.","instructions_ar":"اقرأ الرسالة مرة أخرى واختر الإجابة.","items":[{"q":"Which part is the greeting?","answer":"Dear Noura,","explanation":"A greeting starts a note.","explanation_ar":"التحية تبدأ الرسالة.","options":["With love,","Grandma","Please come to my room.","Dear Noura,"],"dok":1,"skill":"letter parts","stage":"guided"},{"q":"Which part is the closing?","answer":"With love,","explanation":"A closing ends the message.","explanation_ar":"الخاتمة تنهي الرسالة.","options":["Dear Noura,","With love,","Thank you for your help.","I have a new book."],"dok":1,"skill":"letter parts","stage":"guided"},{"q":"What does Grandma say Noura is?","answer":"a kind girl","explanation":"Text: You are a kind girl.","explanation_ar":"تقول إنها بنت لطيفة.","options":["a tall girl","a busy baby","a kind girl","a new friend"],"dok":1,"skill":"character","stage":"guided"},{"q":"Where does Grandma want Noura to come after school?","answer":"to her room","explanation":"Text: come to my room.","explanation_ar":"إلى غرفتها.","options":["to the garden","to the kitchen","to her room","to the park"],"dok":1,"skill":"key details: where","stage":"guided"},{"q":"What does Grandma have for Noura?","answer":"a new book","explanation":"Text: I have a new book for you!","explanation_ar":"لديها كتاب جديد.","options":["a new bag","a cake","a kite","a new book"],"dok":1,"skill":"key details","stage":"guided"},{"q":"How does Grandma feel about Noura?","answer":"She loves her and is thankful.","explanation":"She says thank you and With love.","explanation_ar":"تحبها وتشكرها.","options":["She loves her and is thankful.","She is angry with her.","She does not know her.","She is scared of her."],"dok":2,"skill":"character feelings","stage":"guided"}]},{"id":"RW-L01-U2-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Fill in the Character Web for Noura. Use the story and the note.","instructions_ar":"أكمل شبكة الشخصية لنورة من القصة والرسالة.","items":[{"q":"What does Noura do in the story?","answer":"She puts the plates on the table.","explanation":"An action from the story.","explanation_ar":"فعل من القصة.","dok":1,"skill":"character actions","stage":"freer"},{"q":"What does Noura do in the note?","answer":"She helps Mother and plays with Dana.","explanation":"An action from the note.","explanation_ar":"فعل من الرسالة.","dok":1,"skill":"character actions","stage":"freer"},{"q":"What does Grandma say about Noura?","answer":"You are a kind girl.","explanation":"Grandma's words.","explanation_ar":"كلمات الجدة.","dok":1,"skill":"character","stage":"freer"},{"q":"Write one word that tells what Noura is like.","answer":"kind","explanation":"kind / helpful / happy","explanation_ar":"لطيفة / تساعد / سعيدة","dok":2,"skill":"character traits","stage":"freer"}]},{"id":"RW-L01-U2-LS3-A4","type":"open","stage":"production","instructions":"Writing: Write about a character.","instructions_ar":"اكتب عن شخصية.","items":[{"q":"Choose a character from the story (not Noura). Write the name.","answer":"Grandfather","explanation":"Any character except Noura.","explanation_ar":"أي شخصية غير نورة.","dok":1,"skill":"characters","stage":"production"},{"q":"What does this character do? Write one sentence.","answer":"Grandfather waters the garden.","explanation":"Name + action.","explanation_ar":"الاسم + الفعل.","dok":1,"skill":"character actions","stage":"production"},{"q":"How does this character feel? Why?","answer":"He is happy because he eats with his family.","explanation":"Feeling + reason.","explanation_ar":"الشعور + السبب.","dok":2,"skill":"character feelings","stage":"production"},{"q":"Who is a kind person in YOUR family? What does he or she do?","answer":"My grandmother is kind. She makes me tea.","explanation":"Person + kind action.","explanation_ar":"شخص + فعل لطيف.","dok":2,"skill":"connect","stage":"production"}]},{"id":"RW-L01-U2-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"A Note from Grandma\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “A Note from Grandma”.","answer":"50 words","title":"A Note from Grandma","body":"Dear Noura,\n\nThank you for your help today. You are a kind girl. You help Mother in the kitchen, and you play with baby Dana. Our home is happy with you in it.\n\nPlease come to my room after school. I have a new book for you!\n\nWith love,\n\nGrandma","words":50,"limit":90}],"time_limit_sec":90},{"id":"RW-L01-U2-LS3-ORG","type":"organizer","organizer":"Character Web","instructions":"Organizer: Write the character's name in the middle. Write what the character does, says and feels.","items":[{"q":"Character: Noura","answer":"Noura"},{"q":"What she does","answer":"helps Mother in the kitchen; plays with baby Dana"},{"q":"What people say about her","answer":"Grandma says: You are a kind girl."},{"q":"How she feels","answer":"happy"}]}],"game":{"name":"Character Charades","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Character match: an animated action plays (e.g., watering plants); the child taps the right character from four faces. 12 rounds; correct answers unlock a sticker for the family album.","A student picks a card and acts out the action without speaking.","The team guesses the character and the action in English: \"Grandfather! He waters the garden!\"","Correct character = 1 point; correct action sentence = 1 more point.","Each round has 30 seconds.","Teams take turns; play 12 cards."],"data":[]},"exit_quiz":[{"q":"Characters are the ___ in a story.","answer":"people or animals","explanation":"Characters are people or animals.","explanation_ar":"الشخصيات أشخاص أو حيوانات.","options":["people or animals","pictures only","places","titles"],"dok":1,"skill":"characters"},{"q":"The main character is ___.","answer":"the most important character","explanation":"The story is mostly about the main character.","explanation_ar":"الشخصية الرئيسية هي الأهم.","options":["the last word","the first place","the most important character","the smallest person"],"dok":1,"skill":"main character"},{"q":"In the note, who is kind?","answer":"Noura","explanation":"Grandma says: You are a kind girl.","explanation_ar":"نورة هي اللطيفة.","options":["Faris","Father","Noura","Dana"],"dok":1,"skill":"character"},{"q":"What does a note start with?","answer":"a greeting, like *Dear Noura,*","explanation":"Notes start with a greeting.","explanation_ar":"الرسالة تبدأ بتحية.","options":["a greeting, like *Dear Noura,*","a closing, like *With love,*","a name only","a question"],"dok":1,"skill":"letter parts"},{"q":"What comes after *With love,* in the note?","answer":"the writer's name","explanation":"The name comes last.","explanation_ar":"الاسم يأتي في النهاية.","options":["the greeting","the writer's name","a question","the title"],"dok":1,"skill":"letter parts"},{"q":"Which character waters the garden?","answer":"Grandfather","explanation":"From the story: Grandfather waters the garden.","explanation_ar":"الجد يسقي الحديقة.","options":["Grandma","Grandfather","Mother","Noura"],"dok":1,"skill":"characters"},{"q":"Grandma writes *Thank you for your help today.* Why?","answer":"Noura helps at home.","explanation":"Noura helps Mother and plays with Dana.","explanation_ar":"لأن نورة تساعد في البيت.","options":["Noura is sick.","Noura goes to the park.","Noura has a new bag.","Noura helps at home."],"dok":2,"skill":"character"},{"q":"Which word best describes Grandma in the note?","answer":"loving","explanation":"She thanks Noura and writes *With love*.","explanation_ar":"الجدة محبة.","options":["angry","lazy","scared","loving"],"dok":2,"skill":"character traits"},{"q":"Which is a character in BOTH the story and the note?","answer":"Mother","explanation":"Mother is in the story and in the note.","explanation_ar":"الأم موجودة في القصة والرسالة.","options":["Mother","Faris","Grandfather","Father"],"dok":2,"skill":"connect texts"},{"q":"We learn that Noura is helpful from ___.","answer":"what she does and what Grandma says","explanation":"Her actions and Grandma's words show it.","explanation_ar":"من أفعالها وكلام جدتها.","options":["the color of her hair","what she does and what Grandma says","the name of her school","the title only"],"dok":3,"skill":"character evidence"}],"images":[{"id":"IMG-RW-L01-U2-LS3-V01","prompt":"Picture for the word 'character': a book open with small figures of people stepping out of it"},{"id":"IMG-RW-L01-U2-LS3-V02","prompt":"Picture for the word 'note': a folded small card with a heart on it"},{"id":"IMG-RW-L01-U2-LS3-V03","prompt":"Picture for the word 'dear': the top of a letter with a pen beside it"},{"id":"IMG-RW-L01-U2-LS3-V04","prompt":"Picture for the word 'kind': a girl giving her umbrella to a friend"},{"id":"IMG-RW-L01-U2-LS3-V05","prompt":"Picture for the word 'thank you': a child receiving a gift and smiling"},{"id":"IMG-RW-L01-U2-LS3-V06","prompt":"Picture for the word 'please': a boy asking politely with an open hand"},{"id":"IMG-RW-L01-U2-LS3-V07","prompt":"Picture for the word 'after': a clock and a plate with an arrow pointing to children playing"},{"id":"IMG-RW-L01-U2-LS3-01","prompt":"Grandma writes a note next to a new book."},{"id":"IMG-RW-L01-U2-LS3-02","prompt":"A web with Noura in the middle and three boxes around her."},{"id":"IMG-RW-L01-U2-LS3-03","prompt":"A note card with four colored parts marked."}],"audio":[{"id":"AUD-RW-L01-U2-LS3-V01","script":"character. Noura is a character in the story."},{"id":"AUD-RW-L01-U2-LS3-V02","script":"note. Grandma writes a note."},{"id":"AUD-RW-L01-U2-LS3-V03","script":"dear. Dear Omar, thank you for the ball."},{"id":"AUD-RW-L01-U2-LS3-V04","script":"kind. My teacher is kind."},{"id":"AUD-RW-L01-U2-LS3-V05","script":"thank you. Thank you for the gift."},{"id":"AUD-RW-L01-U2-LS3-V06","script":"please. Please sit down."},{"id":"AUD-RW-L01-U2-LS3-V07","script":"after. We play after lunch."},{"id":"AUD-RW-L01-U2-LS3-T1","script":"Dear Noura, Thank you for your help today. You are a kind girl. You help Mother in the kitchen, and you play with baby Dana. Our home is happy with you in it. Please come to my room after school. I have a new book for you! With love, Grandma"},{"id":"AUD-RW-L01-U2-LS3-VID","script":"Who is in the story? The people in a story are the characters. Noura is the main character. The story is mostly about her. What does she do? She puts the plates on the table. How does she feel? Happy! Dear Noura, Thank you for your help today. You are a kind girl… A note has a greeting, a message, a closing and a name. Find the characters. Find the parts. You can do it!"}]},{"id":"RW-L01-U2-LS4","title":"Writing Skill: Naming words and capital letters for names","lesson_type":"writing_skill","objectives":["tell the difference between a naming word (mother, house) and a special name (Hessa, Taif)","write special names of people and places with a capital letter","write sentences about family members that include their names"],"objectives_ar":["التمييز بين كلمة التسمية (mother, house) والاسم الخاص (Hessa, Taif).","كتابة أسماء الأشخاص والأماكن الخاصة بحرف كبير.","كتابة جمل عن أفراد الأسرة تتضمن أسماءهم."],"success_criteria":["I can find naming words and special names.","I can write names with a capital letter.","I can write a sentence about my family with a name."],"success_criteria_ar":["أستطيع إيجاد كلمات التسمية والأسماء الخاصة.","أستطيع كتابة الأسماء بحرف كبير.","أستطيع كتابة جملة عن أسرتي فيها اسم."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"naming word","pos":"noun","ipa":"/ˈneɪmɪŋ wɝd/","definition":"a word for a person, place or thing (a noun)","arabic":"كلمة تسمية (اسم)","example":"*Garden* is a naming word.","image_id":"IMG-RW-L01-U2-LS4-V01","audio_id":"AUD-RW-L01-U2-LS4-V01","tier":"core"},{"word":"special name","pos":"noun","ipa":"/ˈspɛʃəl neɪm/","definition":"the name of one person or one place","arabic":"اسم خاص (علم)","example":"*Hessa* is a special name.","image_id":"IMG-RW-L01-U2-LS4-V02","audio_id":"AUD-RW-L01-U2-LS4-V02","tier":"core"},{"word":"cousin","pos":"noun","ipa":"/ˈkʌzən/","definition":"the child of your aunt or uncle","arabic":"ابن العم / ابن الخال","example":"My cousin lives in Abha.","image_id":"IMG-RW-L01-U2-LS4-V03","audio_id":"AUD-RW-L01-U2-LS4-V03","tier":"core"},{"word":"uncle","pos":"noun","ipa":"/ˈʌŋkəl/","definition":"the brother of your mother or father","arabic":"عم / خال","example":"My uncle has a big car.","image_id":"IMG-RW-L01-U2-LS4-V04","audio_id":"AUD-RW-L01-U2-LS4-V04","tier":"core"},{"word":"aunt","pos":"noun","ipa":"/ænt/","definition":"the sister of your mother or father","arabic":"عمة / خالة","example":"My aunt makes kabsa.","image_id":"IMG-RW-L01-U2-LS4-V05","audio_id":"AUD-RW-L01-U2-LS4-V05","tier":"core"},{"word":"live","pos":"verb","ipa":"/lɪv/","definition":"to have your home in a place","arabic":"يسكن / يعيش","example":"We live in a big house.","image_id":"IMG-RW-L01-U2-LS4-V06","audio_id":"AUD-RW-L01-U2-LS4-V06","tier":"core"},{"word":"our","pos":"determiner","ipa":"/aʊr/","definition":"belonging to us","arabic":"ـنا (ملكيتنا)","example":"Our garden has a palm tree.","image_id":"IMG-RW-L01-U2-LS4-V07","audio_id":"AUD-RW-L01-U2-LS4-V07","tier":"core"}],"explanation":{"text":"A **naming word** is a word for any person, place or thing: *mother, uncle, house, garden*. It starts with a **small letter** (not at the start of a sentence).\n\nA **special name** is the name of **one** person or **one** place: *Hessa, Faris, Taif, Abha*. It always starts with a **capital letter**.\n\nAsk: Is it **any** mother, or **one** person called Hessa? Any → small letter. One special name → capital letter.","examples":["mother → **H**essa","brother → **F**aris","sister → **D**ana","uncle → **U**ncle **S**aad","city → **T**aif","city → **R**iyadh","My cousin is **M**ajed.","My aunt **N**oura lives in **A**bha.","We live in a small house in **J**eddah."],"common_errors":["✗ My Mother is kind. → ✓ My mother is kind. (After *my*, mother is a naming word → small m.)","✗ my uncle is saad. → ✓ My uncle is Saad. (First word and special name need capitals.)","✗ We live in abha. → ✓ We live in Abha. (Abha is the special name of a city.)","✗ My Brother Faris is Tall. → ✓ My brother Faris is tall. (Only the special name gets a capital in the middle.)","✗ I have a cousin, she name is Reem. → ✓ I have a cousin. Her name is Reem. (Use **her name**.)","✗ my aunt live in Dammam. → ✓ My aunt lives in Dammam. (Capital M; one person → **lives**.)"],"arabic":"كلمة التسمية (naming word) تدل على أي شخص أو مكان أو شيء مثل mother وhouse، وتُكتب بحرف صغير إذا لم تكن في أول الجملة.\n\nالاسم الخاص (special name) هو اسم شخص واحد أو مكان واحد بعينه مثل Hessa وTaif، ويبدأ دائمًا بحرف كبير.\n\nاسأل: هل هي أي أم؟ أم شخص اسمه حصة؟ أي أم ← حرف صغير. اسم خاص ← حرف كبير."},"video":{"script":[{"time":"00:00–00:15","narration":"Mother or Hessa? Brother or Faris? Let's find out!","on_screen":"Naming word or special name?","visual":"Two doors: one labelled with a small 'm', one with a big 'H' and a star."},{"time":"00:15–00:45","narration":"Mother is a naming word. Every family has a mother. Small m!","on_screen":"mother","visual":"Many different mothers appear in a row; the word 'mother' stays small."},{"time":"00:45–01:10","narration":"Hessa is a special name. It is the name of one person. Capital H!","on_screen":"Hessa","visual":"One woman steps forward; a gold star lands on the capital H."},{"time":"01:10–01:40","narration":"Places too! A city is a naming word. Taif is a special name. Capital T!","on_screen":"city → Taif","visual":"A map of Saudi Arabia; a pin drops on Taif and the T grows big."},{"time":"01:40–02:05","narration":"Read Noura's family page. Find the capitals. Fahad, Hessa, Faris, Dana, Taif!","on_screen":"Find the special names!","visual":"The model text appears; each special name sparkles one by one."},{"time":"02:05–02:20","narration":"Any person or place – small letter. One special name – capital letter!","on_screen":"small ↔ CAPITAL","visual":"Saqr balances a small letter and a capital letter on a seesaw."}],"captions_ar":["أم أو حصة؟ أخ أو فارس؟ هيا نكتشف!","mother كلمة تسمية؛ لكل أسرة أم، لذلك نكتبها بحرف صغير.","Hessa اسم خاص لشخص واحد، لذلك نكتبها بحرف H كبير.","والأماكن أيضًا: city كلمة تسمية، وTaif اسم خاص بحرف T كبير.","اقرأ صفحة نورة عن أسرتها وابحث عن الحروف الكبيرة: فهد، حصة، فارس، دانة، الطائف!","أي شخص أو مكان بحرف صغير، والاسم الخاص بحرف كبير!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Noura: friendly girl. Saqr: playful."},"texts":[{"type":"model","title":"My Family (from Noura's Notebook)","body":"This is my family. My father is Fahad. My mother is Hessa. My brother Faris is eleven. My baby sister is Dana.\n\nMy grandmother and my grandfather live with us. We live in Taif. Our house has a big garden.","word_count":40,"audio_id":"AUD-RW-L01-U2-LS4-T1","id":"TXT-RW-L01-U2-LS4-1","genre":"model text","role":"model","difficulty":"BR–200L","glossary":[],"annotations":["**f**ather, **m**other, **b**rother, **s**ister – naming words for family start with a small letter.","**F**ahad, **H**essa, **F**aris, **D**ana – special names of people start with a capital letter.","**T**aif – the special name of a place starts with a capital letter.","**h**ouse, **g**arden – naming words for places start with a small letter.","**T**his, **M**y, **O**ur – the first word of every sentence starts with a capital letter."]}],"activities":[{"id":"RW-L01-U2-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Which word needs a capital letter?","instructions_ar":"أي كلمة تحتاج إلى حرف كبير؟","items":[{"q":"Which word in *my cousin badr is nine.* is a special name?","answer":"badr","explanation":"Badr is the name of one boy.","explanation_ar":"بدر اسم شخص.","options":["cousin","nine","badr","is"],"dok":1,"skill":"special names","stage":"controlled"},{"q":"Which word in *we visit our aunt in dammam.* is a special name?","answer":"dammam","explanation":"Dammam is the name of a city.","explanation_ar":"الدمام اسم مدينة.","options":["dammam","aunt","visit","our"],"dok":1,"skill":"special names","stage":"controlled"},{"q":"Which word in *her uncle saad has a car.* is a special name?","answer":"saad","explanation":"Saad is a person's name.","explanation_ar":"سعد اسم شخص.","options":["uncle","saad","car","has"],"dok":1,"skill":"special names","stage":"controlled"},{"q":"Which word is a naming word, NOT a special name?","answer":"garden","explanation":"Garden can be any garden.","explanation_ar":"الحديقة كلمة تسمية عامة.","options":["Abha","Hessa","Riyadh","garden"],"dok":1,"skill":"naming words","stage":"controlled"},{"q":"Which word is a special name?","answer":"Makkah","explanation":"Makkah is the name of one city.","explanation_ar":"مكة اسم خاص لمدينة.","options":["city","house","Makkah","room"],"dok":1,"skill":"special names","stage":"controlled"},{"q":"Which word is a naming word for a person?","answer":"aunt","explanation":"Aunt can be any aunt.","explanation_ar":"العمة كلمة تسمية لشخص.","options":["Reem","aunt","Taif","kitchen"],"dok":1,"skill":"naming words","stage":"controlled"}]},{"id":"RW-L01-U2-LS4-A2","type":"open","stage":"guided","instructions":"Guided practice: Write each sentence correctly. Use capital letters for special names.","instructions_ar":"اكتب كل جملة بشكل صحيح مستخدمًا الحرف الكبير للأسماء الخاصة.","items":[{"q":"my sister is reem.","answer":"My sister is Reem.","explanation":"Capital M and capital R.","explanation_ar":"M كبيرة وR كبيرة.","dok":1,"skill":"editing","stage":"guided"},{"q":"our uncle lives in abha.","answer":"Our uncle lives in Abha.","explanation":"Capital O and capital A for Abha.","explanation_ar":"O كبيرة وA كبيرة.","dok":1,"skill":"editing","stage":"guided"},{"q":"my father is khalid.","answer":"My father is Khalid.","explanation":"Khalid is a special name.","explanation_ar":"خالد اسم خاص.","dok":1,"skill":"editing","stage":"guided"},{"q":"hessa and dana are in the room.","answer":"Hessa and Dana are in the room.","explanation":"Two special names.","explanation_ar":"اسمان خاصان.","dok":2,"skill":"editing","stage":"guided"},{"q":"my aunt and my cousin live in riyadh.","answer":"My aunt and my cousin live in Riyadh.","explanation":"Only the first word and Riyadh need capitals.","explanation_ar":"أول كلمة والرياض فقط.","dok":2,"skill":"editing","stage":"guided"},{"q":"grandfather saleh tells stories in makkah.","answer":"Grandfather Saleh tells stories in Makkah.","explanation":"Capitals for the first word, Saleh and Makkah.","explanation_ar":"حروف كبيرة لأول كلمة وصالح ومكة.","dok":2,"skill":"editing","stage":"guided"}]},{"id":"RW-L01-U2-LS4-A3","type":"open","stage":"freer","instructions":"Freer practice: Sort the words into two groups.","instructions_ar":"صنّف الكلمات في مجموعتين.","items":[{"q":"Write the naming words: brother, Faris, city, Jeddah.","answer":"brother, city","explanation":"Any brother, any city.","explanation_ar":"أي أخ وأي مدينة.","dok":1,"skill":"sorting","stage":"freer"},{"q":"Write the special names: brother, Faris, city, Jeddah.","answer":"Faris, Jeddah","explanation":"One person and one city.","explanation_ar":"شخص ومدينة بعينهما.","dok":1,"skill":"sorting","stage":"freer"},{"q":"Write a special name for a city you know.","answer":"Madinah","explanation":"Any city name with a capital.","explanation_ar":"أي اسم مدينة بحرف كبير.","dok":1,"skill":"special names","stage":"freer"},{"q":"Write the special name of someone in your family.","answer":"Saud","explanation":"Any real name with a capital.","explanation_ar":"أي اسم بحرف كبير.","dok":1,"skill":"special names","stage":"freer"}]},{"id":"RW-L01-U2-LS4-A4","type":"open","stage":"production","instructions":"Writing: Write 4 sentences about your family. Use names.","instructions_ar":"اكتب 4 جمل عن أسرتك مستخدمًا الأسماء.","items":[{"q":"Write about your father or mother. Use the name.","answer":"My father is Hamad.","explanation":"Naming word + special name.","explanation_ar":"كلمة تسمية + اسم خاص.","dok":1,"skill":"sentence writing","stage":"production"},{"q":"Write about a brother, sister or cousin. Use the name.","answer":"My cousin is Lulu.","explanation":"Capital for the name.","explanation_ar":"حرف كبير للاسم.","dok":1,"skill":"sentence writing","stage":"production"},{"q":"Write where your family lives. Use the city name.","answer":"We live in Taif.","explanation":"Capital for the city.","explanation_ar":"حرف كبير للمدينة.","dok":2,"skill":"sentence writing","stage":"production"},{"q":"Write about an uncle or an aunt. Use the name and a city.","answer":"My uncle Nasser lives in Tabuk.","explanation":"Two special names.","explanation_ar":"اسمان خاصان.","dok":2,"skill":"sentence writing","stage":"production"}]}],"game":{"name":"Capital Star Hunt","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Tap-the-name: a sentence in all small letters appears; the child taps every special name. Tapped names jump into capitals with a star. 10 sentences; a bonus star for no mistakes.","Pairs walk around the room to the 10 sentence posters.","At each poster, they find the special names and write them with capitals on their sheet.","They put a star sticker next to each special name on the poster.","After 8 minutes, the class checks each poster together.","Each correct special name = 1 point for the pair."],"data":[]},"exit_quiz":[{"q":"A special name always starts with ___.","answer":"a capital letter","explanation":"Special names start with capital letters.","explanation_ar":"الاسم الخاص يبدأ بحرف كبير.","options":["a capital letter","a small letter","a period","a number"],"dok":1,"skill":"rule"},{"q":"Which is a special name?","answer":"Fahad","explanation":"Fahad is the name of one person.","explanation_ar":"فهد اسم خاص.","options":["Fahad","father","uncle","brother"],"dok":1,"skill":"special names"},{"q":"Which is a naming word?","answer":"sister","explanation":"Sister can be any sister.","explanation_ar":"sister كلمة تسمية.","options":["Dana","Abha","sister","Reem"],"dok":1,"skill":"naming words"},{"q":"Which sentence is written correctly?","answer":"My aunt lives in Hail.","explanation":"Capital M and capital H for Hail only.","explanation_ar":"M وH فقط بحرف كبير.","options":["My Aunt lives in Hail.","My aunt lives in Hail.","my aunt lives in hail.","My aunt lives in hail."],"dok":1,"skill":"capitals"},{"q":"Which word should have a capital letter? *we live in tabuk.*","answer":"tabuk and we","explanation":"The first word and the city need capitals.","explanation_ar":"أول كلمة واسم المدينة.","options":["live and in","only in","only live","tabuk and we"],"dok":2,"skill":"capitals"},{"q":"The brother of your father is your ___.","answer":"uncle","explanation":"Your father's brother is your uncle.","explanation_ar":"أخو أبيك هو عمك.","options":["aunt","cousin","uncle","sister"],"dok":1,"skill":"vocabulary"},{"q":"The child of your aunt is your ___.","answer":"cousin","explanation":"Your aunt's child is your cousin.","explanation_ar":"ابن خالتك أو عمتك.","options":["cousin","uncle","grandfather","baby"],"dok":1,"skill":"vocabulary"},{"q":"Which is correct?","answer":"My mother is Hessa.","explanation":"Small m for mother; capital H for Hessa.","explanation_ar":"m صغيرة وH كبيرة.","options":["My Mother is hessa.","my mother is Hessa.","My mother is hessa.","My mother is Hessa."],"dok":2,"skill":"capitals"},{"q":"Why does *Taif* start with a capital letter?","answer":"It is the name of one city.","explanation":"It is a special name of a place.","explanation_ar":"لأنه اسم مدينة بعينها.","options":["It is a long word.","It is at the end.","It is a person.","It is the name of one city."],"dok":2,"skill":"rule"},{"q":"Which sentence has the right number of capital letters?","answer":"My cousin Badr and I play in Jeddah.","explanation":"Capitals for My, Badr, I and Jeddah only.","explanation_ar":"My وBadr وI وJeddah فقط.","options":["My Cousin Badr and I play in Jeddah.","My cousin Badr and I play in Jeddah.","my cousin badr and i play in jeddah.","My cousin badr and I Play in Jeddah."],"dok":3,"skill":"capitals"}],"images":[{"id":"IMG-RW-L01-U2-LS4-V01","prompt":"Picture for the word 'naming word': word cards for a person, a house and a ball with icons"},{"id":"IMG-RW-L01-U2-LS4-V02","prompt":"Picture for the word 'special name': a name tag with a star on it"},{"id":"IMG-RW-L01-U2-LS4-V03","prompt":"Picture for the word 'cousin': two children of the same age with their mothers who are sisters"},{"id":"IMG-RW-L01-U2-LS4-V04","prompt":"Picture for the word 'uncle': a smiling man in a thobe with a car key"},{"id":"IMG-RW-L01-U2-LS4-V05","prompt":"Picture for the word 'aunt': a woman serving a plate of rice and chicken"},{"id":"IMG-RW-L01-U2-LS4-V06","prompt":"Picture for the word 'live': a family standing in front of their home"},{"id":"IMG-RW-L01-U2-LS4-V07","prompt":"Picture for the word 'our': two children pointing to the same garden"},{"id":"IMG-RW-L01-U2-LS4-01","prompt":"A notebook page with drawings of Noura's family."},{"id":"IMG-RW-L01-U2-LS4-02","prompt":"Many mothers on one side and one woman with a star on the other."},{"id":"IMG-RW-L01-U2-LS4-03","prompt":"A simple map of Saudi Arabia with pins on cities."}],"audio":[{"id":"AUD-RW-L01-U2-LS4-V01","script":"naming word. *Garden* is a naming word."},{"id":"AUD-RW-L01-U2-LS4-V02","script":"special name. *Hessa* is a special name."},{"id":"AUD-RW-L01-U2-LS4-V03","script":"cousin. My cousin lives in Abha."},{"id":"AUD-RW-L01-U2-LS4-V04","script":"uncle. My uncle has a big car."},{"id":"AUD-RW-L01-U2-LS4-V05","script":"aunt. My aunt makes kabsa."},{"id":"AUD-RW-L01-U2-LS4-V06","script":"live. We live in a big house."},{"id":"AUD-RW-L01-U2-LS4-V07","script":"our. Our garden has a palm tree."},{"id":"AUD-RW-L01-U2-LS4-T1","script":"This is my family. My father is Fahad. My mother is Hessa. My brother Faris is eleven. My baby sister is Dana. My grandmother and my grandfather live with us. We live in Taif. Our house has a big garden."},{"id":"AUD-RW-L01-U2-LS4-VID","script":"Mother or Hessa? Brother or Faris? Let's find out! Mother is a naming word. Every family has a mother. Small m! Hessa is a special name. It is the name of one person. Capital H! Places too! A city is a naming word. Taif is a special name. Capital T! Read Noura's family page. Find the capitals. Fahad, Hessa, Faris, Dana, Taif! Any person or place – small letter. One special name – capital letter!"}]},{"id":"RW-L01-U2-LS5","title":"Writing Workshop: My Family","lesson_type":"writing_workshop","objectives":["plan a family drawing with labels and special names","write 4 sentences about their family in a clear order (opening sentence, people, feeling sentence)","edit for capital letters (sentence starts, I, special names) and periods, then publish"],"objectives_ar":["التخطيط لرسم الأسرة مع بطاقات وأسماء خاصة.","كتابة 4 جمل عن أسرتهم بترتيب واضح: جملة افتتاحية، ثم الأشخاص، ثم جملة عن الشعور.","تدقيق الحروف الكبيرة والنقاط ثم نشر الكتابة."],"success_criteria":["I can draw and label my family.","I can write 4 sentences in a good order.","I can check capitals and periods before I share."],"success_criteria_ar":["أستطيع رسم أسرتي وكتابة البطاقات.","أستطيع كتابة 4 جمل بترتيب جيد.","أستطيع مراجعة الحروف الكبيرة والنقاط قبل المشاركة."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"love","pos":"verb","ipa":"/lʌv/","definition":"to like someone very, very much","arabic":"يحب (كثيرًا)","example":"I love my grandmother.","image_id":"IMG-RW-L01-U2-LS5-V01","audio_id":"AUD-RW-L01-U2-LS5-V01","tier":"core"},{"word":"young","pos":"adjective","ipa":"/jʌŋ/","definition":"not old; a short time alive","arabic":"صغير السن","example":"My cousin is very young.","image_id":"IMG-RW-L01-U2-LS5-V02","audio_id":"AUD-RW-L01-U2-LS5-V02","tier":"core"},{"word":"old","pos":"adjective","ipa":"/oʊld/","definition":"not young; a long time alive","arabic":"كبير السن / قديم","example":"My grandfather is old and wise.","image_id":"IMG-RW-L01-U2-LS5-V03","audio_id":"AUD-RW-L01-U2-LS5-V03","tier":"core"},{"word":"funny","pos":"adjective","ipa":"/ˈfʌni/","definition":"makes you laugh","arabic":"مضحك","example":"My uncle tells funny stories.","image_id":"IMG-RW-L01-U2-LS5-V04","audio_id":"AUD-RW-L01-U2-LS5-V04","tier":"core"},{"word":"take care of","pos":"verb","ipa":"/teɪk kɛr ʌv/","definition":"to look after and help","arabic":"يعتني بـ","example":"I take care of my baby sister.","image_id":"IMG-RW-L01-U2-LS5-V05","audio_id":"AUD-RW-L01-U2-LS5-V05","tier":"core"},{"word":"both","pos":"pronoun","ipa":"/boʊθ/","definition":"the two together","arabic":"كلاهما","example":"Both my brothers are tall.","image_id":"IMG-RW-L01-U2-LS5-V06","audio_id":"AUD-RW-L01-U2-LS5-V06","tier":"core"},{"word":"every day","pos":"phrase","ipa":"/ˈɛvri deɪ/","definition":"on all days","arabic":"كل يوم","example":"I read every day.","image_id":"IMG-RW-L01-U2-LS5-V07","audio_id":"AUD-RW-L01-U2-LS5-V07","tier":"core"}],"explanation":{"text":"When you write about your family, put your sentences in a good **order**.\n\n**Start** with an opening sentence: *This is my family.* **Then** write one sentence for each person. **End** with a feeling sentence: *I love my family.*\n\nUse the five steps: **plan → draft → revise → edit → publish**. Remember capital letters for special names!","examples":["Opening: **This is my family.**","Opening: **There are five people in my family.**","Person: **My father is Hamad. He is tall.**","Person: **My mother is Lulu. She is kind.**","Person: **My brother Ali is funny.**","Person: **My grandmother is old and wise.**","Feeling: **I love my family.**","Feeling: **My family is happy together.**","Revise: *My sister is Sara.* → **My young sister is Sara.**"],"common_errors":["✗ My family is five. → ✓ There are five people in my family. (Use **There are … people**.)","✗ My brother name is Ali. → ✓ My brother's name is Ali. (Add **'s**: brother's name.)","✗ She is old woman. → ✓ She is an old woman. (Use **an** before old.)","✗ I love my family very. → ✓ I love my family very much. (Say **very much** at the end.)","✗ My father he is funny. → ✓ My father is funny. (One subject only.)","✗ my mother is lulu → ✓ My mother is Lulu. (Capitals for the first word and the name; a period at the end.)"],"arabic":"عندما تكتب عن أسرتك رتّب جملك: ابدأ بجملة افتتاحية مثل This is my family، ثم اكتب جملة عن كل شخص، ثم اختم بجملة عن مشاعرك مثل I love my family.\n\nاتبع الخطوات الخمس: خطِّط، اكتب المسودة، حسِّن، دقِّق، انشر.\n\nانتبه: لا نقول My family is five، بل There are five people in my family."},"video":{"script":[{"time":"00:00–00:15","narration":"Sami wants to write about his family. Let's help him!","on_screen":"My Family","visual":"Sami sits with crayons and a blank page; Grandpa Saleh waves from the side."},{"time":"00:15–00:45","narration":"Plan: draw your family. Write a name under each person.","on_screen":"1 Plan","visual":"Sami draws his parents, his little sister and Grandpa Saleh; name labels appear."},{"time":"00:45–01:20","narration":"Draft: This is my family. My father is Hamad. My mother is Lulu. My grandfather is Saleh. I love my family.","on_screen":"2 Draft – start · people · end","visual":"Sentences appear in three colors: opening (blue), people (green), feeling (coral)."},{"time":"01:20–01:45","narration":"Revise: add a describing word. My grandfather is Saleh… My grandfather Saleh is funny!","on_screen":"3 Revise ➕ funny","visual":"The word 'funny' bounces into the sentence; Grandpa laughs."},{"time":"01:45–02:10","narration":"Edit: capital letters for names, a period at the end. Hamad, Lulu, Saleh – capitals!","on_screen":"4 Edit ✔ capitals","visual":"Names glow green; periods glow red."},{"time":"02:10–02:40","narration":"Publish: put your family page on the Family Tree wall. Read it to a friend!","on_screen":"5 Publish 🌳","visual":"Sami adds his page to a big paper tree on the classroom wall next to Noura's page."}],"captions_ar":["سامي يريد أن يكتب عن أسرته. لنساعده!","خطِّط: ارسم أسرتك واكتب اسمًا تحت كل شخص.","المسودة: هذه أسرتي. أبي حمد. أمي لولو. جدي صالح. أحب أسرتي.","حسِّن: أضف كلمة وصفية: جدي صالح مضحك!","دقِّق: حروف كبيرة للأسماء ونقطة في النهاية.","انشر: ضع صفحتك على شجرة الأسرة في الفصل واقرأها لصديقك!"],"voice":"Narrator: American English, warm female teacher, speed 0.8. Sami: cheerful boy voice reading his family page."},"texts":[],"activities":[{"id":"RW-L01-U2-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which is a good opening sentence?","answer":"This is my family.","explanation":"An opening sentence tells the topic.","explanation_ar":"الجملة الافتتاحية تذكر الموضوع.","options":["I love my family.","This is my family.","My sister is Sara.","The end."],"dok":1,"skill":"order of sentences","stage":"controlled"},{"q":"Which is a good feeling sentence for the end?","answer":"I love my family.","explanation":"A feeling sentence ends the writing.","explanation_ar":"جملة المشاعر في النهاية.","options":["I love my family.","This is my family.","My father is Hamad.","My house has a door."],"dok":1,"skill":"order of sentences","stage":"controlled"},{"q":"My grandfather is not young. He is ___.","answer":"old","explanation":"Old is the opposite of young.","explanation_ar":"old عكس young.","options":["old","funny","busy","small"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"My uncle makes us laugh. He is ___.","answer":"funny","explanation":"Funny means makes you laugh.","explanation_ar":"funny تعني مضحك.","options":["old","young","ready","funny"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"I help my baby brother eat. I ___ him.","answer":"take care of","explanation":"Take care of = look after.","explanation_ar":"take care of تعني يعتني بـ.","options":["look for","open","plan","take care of"],"dok":2,"skill":"vocabulary","stage":"controlled"},{"q":"Which sentence tells how many people are in a family?","answer":"There are six people in my family.","explanation":"We say *There are … people in my family*.","explanation_ar":"نقول There are ... people.","options":["My family is six.","My family has six years.","There are six people in my family.","Six is my family."],"dok":2,"skill":"sentence frames","stage":"controlled"}]},{"id":"RW-L01-U2-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the words in order. Remember capitals and periods.","instructions_ar":"رتّب الكلمات وتذكّر الحروف الكبيرة والنقطة.","items":[{"q":"Build the opening sentence.","answer":"This is my family.","explanation":"Opening: This is my family.","explanation_ar":"الجملة الافتتاحية.","stage":"guided","parts":["my","This","family.","is"],"target":["This","is","my","family."]},{"q":"Build a sentence about a kind mother.","answer":"My mother is kind.","explanation":"Person sentence: My mother is kind.","explanation_ar":"جملة عن الأم.","stage":"guided","parts":["kind.","My","mother","is"],"target":["My","mother","is","kind."]},{"q":"Build a sentence about Turki.","answer":"My brother Turki is tall.","explanation":"Name after brother; describing word at the end.","explanation_ar":"الاسم بعد brother والصفة في النهاية.","stage":"guided","parts":["brother","My","Turki","is","tall."],"target":["My","brother","Turki","is","tall."]},{"q":"Build a sentence about Grandma Hessa.","answer":"Grandma Hessa is old.","explanation":"Grandma Hessa is old.","explanation_ar":"الجدة حصة كبيرة في السن.","stage":"guided","parts":["Grandma","Hessa","old.","is"],"target":["Grandma","Hessa","is","old."]},{"q":"Build a sentence about caring for Dana.","answer":"I take care of Dana.","explanation":"I take care of Dana.","explanation_ar":"أعتني بدانة.","stage":"guided","parts":["of","care","Dana.","I","take"],"target":["I","take","care","of","Dana."]},{"q":"Build the feeling sentence.","answer":"I love my family.","explanation":"Feeling sentence: I love my family.","explanation_ar":"جملة المشاعر.","stage":"guided","parts":["I","my","family.","love"],"target":["I","love","my","family."]}]},{"id":"RW-L01-U2-LS5-A3","type":"open","stage":"freer","instructions":"Freer practice: Complete the sentences about YOUR family.","instructions_ar":"أكمل الجمل عن أسرتك.","items":[{"q":"There are ___ people in my family.","answer":"There are five people in my family.","explanation":"A number word.","explanation_ar":"رقم مكتوب بالحروف.","dok":1,"skill":"personal writing","stage":"freer"},{"q":"My father/mother is ___. (name)","answer":"My father is Saud.","explanation":"A special name with a capital.","explanation_ar":"اسم خاص بحرف كبير.","dok":1,"skill":"personal writing","stage":"freer"},{"q":"My ___ is funny/kind/tall.","answer":"My uncle is funny.","explanation":"Family word + describing word.","explanation_ar":"كلمة أسرة + صفة.","dok":2,"skill":"personal writing","stage":"freer"},{"q":"I take care of ___. / ___ takes care of me.","answer":"My grandmother takes care of me.","explanation":"Any true sentence.","explanation_ar":"أي جملة صحيحة.","dok":2,"skill":"personal writing","stage":"freer"}]},{"id":"RW-L01-U2-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write your family page. Then edit and publish.","instructions_ar":"اكتب صفحة أسرتك ثم دققها وانشرها.","items":[{"q":"Write your opening sentence.","answer":"This is my family.","explanation":"An opening sentence.","explanation_ar":"جملة افتتاحية.","dok":1,"skill":"writing","stage":"production"},{"q":"Write two sentences about two people. Use their names.","answer":"My father Hamad is tall. My sister Sara is young.","explanation":"Two people, two names.","explanation_ar":"شخصان واسمان.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your feeling sentence.","answer":"I love my family.","explanation":"A feeling sentence.","explanation_ar":"جملة مشاعر.","dok":1,"skill":"writing","stage":"production"},{"q":"Read your page to a partner. Write one comment your partner gave you.","answer":"She liked 'funny uncle'.","explanation":"One comment.","explanation_ar":"تعليق واحد.","dok":2,"skill":"sharing","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L01-U2-LS5-ORG","type":"organizer","organizer":"Family Plan (opening – people – feeling)","instructions":"Organizer: Draw your family. Then write one idea in each box.","items":[{"q":"Opening sentence","answer":"This is my family."},{"q":"Person 1 (name + one word)","answer":"My father Hamad – tall"},{"q":"Person 2 (name + one word)","answer":"My sister Sara – young"},{"q":"Feeling sentence","answer":"I love my family."}]},{"id":"RW-L01-U2-LS5-WR","type":"writing","instructions":"Writing: Write 4 sentences about your family. Draw your family and write their names. Write 4 sentences about your family. Draw your family and write their names.","instructions_ar":"اكتب 4 جمل عن أسرتك، وارسم أسرتك واكتب أسماءهم.","prompt":"Write 4 sentences about your family. Draw your family and write their names.","checklist":["I started with an opening sentence.","I wrote about two people in my family.","I ended with a feeling sentence.","Special names start with a capital letter.","Every sentence ends with a period.","I used one describing word."],"rubric_id":"RW-RUBRIC-5T","min_words":14,"max_words":50,"organizer":"Family Plan (opening – people – feeling)","items":[{"q":"Write 4 sentences about your family. Draw your family and write their names.","answer":"This is my family. My father Hamad is tall and funny. My young sister is Sara. I love my family.","_w":{"checklist":["I started with an opening sentence.","I wrote about two people in my family.","I ended with a feeling sentence.","Special names start with a capital letter.","Every sentence ends with a period.","I used one describing word."],"min":14,"max":50}}]}],"game":{"name":"Family Sentence Train","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Train builder: four sentence cars arrive in the wrong order; the child drags them onto the track. The engine must be the opening sentence and the last car the feeling sentence. Correct = the train toots and moves; 6 trains.","Each team gets one train set face down.","On \"Go!\", the team reads the cards and builds the train in order on the desk.","The team reads the paragraph aloud.","The teacher checks: correct order = 2 points; correct capitals spotted = 1 bonus point.","Swap sets and play again."],"data":[]},"exit_quiz":[{"q":"Which sentence comes FIRST in a family page?","answer":"This is my family.","explanation":"The opening sentence comes first.","explanation_ar":"الجملة الافتتاحية أولًا.","options":["This is my family.","I love my family.","My sister is Huda.","My mother is kind."],"dok":1,"skill":"order"},{"q":"Which sentence comes LAST?","answer":"My family is happy together.","explanation":"A feeling sentence ends the page.","explanation_ar":"جملة المشاعر في النهاية.","options":["This is my family.","There are four people in my family.","My father is Ali.","My family is happy together."],"dok":1,"skill":"order"},{"q":"Which word is the opposite of *old*?","answer":"young","explanation":"Young is the opposite of old.","explanation_ar":"young عكس old.","options":["funny","kind","young","tall"],"dok":1,"skill":"vocabulary"},{"q":"*Both my sisters are kind.* *Both* means ___.","answer":"the two together","explanation":"Both = the two.","explanation_ar":"both تعني الاثنين معًا.","options":["only one","the two together","nobody","many babies"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence is correct?","answer":"There are three people in my family.","explanation":"Use *There are … people*.","explanation_ar":"نقول There are.","options":["My family is three.","My family three people.","There are three people in my family.","Three is my family people."],"dok":2,"skill":"sentence frames"},{"q":"Which sentence needs a capital letter for a name?","answer":"my cousin is lama.","explanation":"Lama is a name and *my* starts the sentence.","explanation_ar":"لمى اسم، وmy أول الجملة.","options":["This is my house.","my cousin is lama.","I love my family.","My mother is kind."],"dok":2,"skill":"editing"},{"q":"In the *revise* step, Sami changes *My grandfather is Saleh.* to ___.","answer":"My grandfather Saleh is funny.","explanation":"Revising adds a describing word.","explanation_ar":"التحسين يضيف كلمة وصفية.","options":["My grandfather Saleh is funny.","my grandfather is saleh","Grandfather.","Saleh is my."],"dok":2,"skill":"revising"},{"q":"What does the writer do in the *publish* step?","answer":"copies the writing neatly and shares it","explanation":"Publishing = neat copy + share.","explanation_ar":"النشر: نسخة نظيفة ومشاركة.","options":["draws a plan","finds mistakes","chooses a topic","copies the writing neatly and shares it"],"dok":1,"skill":"writing process"},{"q":"Huda says, *I read with my sister every day.* When does she read with her sister?","answer":"on all days","explanation":"Every day means on all days.","explanation_ar":"every day تعني كل يوم.","options":["only on Friday","never","on all days","at night only"],"dok":2,"skill":"vocabulary in context"},{"q":"Which family page is in the best order?","answer":"This is my family. My mother is Mona. My brother is Ali. I love my family.","explanation":"Opening → people → feeling.","explanation_ar":"افتتاح ثم أشخاص ثم مشاعر.","options":["I love my family. This is my family. My brother is Ali. My mother is Mona.","This is my family. My mother is Mona. My brother is Ali. I love my family.","My brother is Ali. I love my family. This is my family. My mother is Mona.","My mother is Mona. This is my family. I love my family. My brother is Ali."],"dok":3,"skill":"order"}],"images":[{"id":"IMG-RW-L01-U2-LS5-V01","prompt":"Picture for the word 'love': a child hugging a grandmother"},{"id":"IMG-RW-L01-U2-LS5-V02","prompt":"Picture for the word 'young': a toddler playing with blocks"},{"id":"IMG-RW-L01-U2-LS5-V03","prompt":"Picture for the word 'old': an elderly man with a white beard smiling"},{"id":"IMG-RW-L01-U2-LS5-V04","prompt":"Picture for the word 'funny': a man telling a story while children laugh"},{"id":"IMG-RW-L01-U2-LS5-V05","prompt":"Picture for the word 'take care of': a girl holding a baby bottle for her baby sister"},{"id":"IMG-RW-L01-U2-LS5-V06","prompt":"Picture for the word 'both': two tall brothers standing back to back"},{"id":"IMG-RW-L01-U2-LS5-V07","prompt":"Picture for the word 'every day': a calendar with a tick on every day"},{"id":"IMG-RW-L01-U2-LS5-01","prompt":"A classroom family tree with leaf pages made by students."},{"id":"IMG-RW-L01-U2-LS5-02","prompt":"A crayon drawing of Sami's family with spaces for names."},{"id":"IMG-RW-L01-U2-LS5-03","prompt":"A toy train with four cars."}],"audio":[{"id":"AUD-RW-L01-U2-LS5-V01","script":"love. I love my grandmother."},{"id":"AUD-RW-L01-U2-LS5-V02","script":"young. My cousin is very young."},{"id":"AUD-RW-L01-U2-LS5-V03","script":"old. My grandfather is old and wise."},{"id":"AUD-RW-L01-U2-LS5-V04","script":"funny. My uncle tells funny stories."},{"id":"AUD-RW-L01-U2-LS5-V05","script":"take care of. I take care of my baby sister."},{"id":"AUD-RW-L01-U2-LS5-V06","script":"both. Both my brothers are tall."},{"id":"AUD-RW-L01-U2-LS5-V07","script":"every day. I read every day."},{"id":"AUD-RW-L01-U2-LS5-VID","script":"Sami wants to write about his family. Let's help him! Plan: draw your family. Write a name under each person. Draft: This is my family. My father is Hamad. My mother is Lulu. My grandfather is Saleh. I love my family. Revise: add a describing word. My grandfather is Saleh… My grandfather Saleh is funny! Edit: capital letters for names, a period at the end. Hamad, Lulu, Saleh – capitals! Publish: put your family page on the Family Tree wall. Read it to a friend!"}]}],"unit_test":[{"q":"The sister of my mother is my ___.","answer":"aunt","explanation":"Your mother's sister is your aunt.","explanation_ar":"أخت أمك خالتك.","options":["uncle","aunt","cousin","brother"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"We wash plates and cook rice in the ___.","answer":"kitchen","explanation":"Cooking happens in the kitchen.","explanation_ar":"الطبخ في المطبخ.","options":["garden","window","kitchen","car"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Hamad's father's father is Hamad's ___.","answer":"grandfather","explanation":"A father's father is a grandfather.","explanation_ar":"أبو الأب هو الجد.","options":["uncle","brother","grandfather","baby"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Please close the ___. It is cold outside.","answer":"door","explanation":"We close a door.","explanation_ar":"نغلق الباب.","options":["door","garden","kitchen","baby"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Majed has many jobs today. He is very ___.","answer":"busy","explanation":"Many jobs = busy.","explanation_ar":"أعمال كثيرة تعني مشغول.","options":["ready","busy","young","old"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"We have flowers and a palm tree in our ___.","answer":"garden","explanation":"Plants grow in a garden.","explanation_ar":"النباتات في الحديقة.","options":["garden","room","door","window"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"The cake is on the table. Lunch is ___!","answer":"ready","explanation":"Food on the table = ready.","explanation_ar":"الطعام جاهز.","options":["busy","funny","old","ready"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Badr is one year old. He is very ___.","answer":"young","explanation":"One year old = very young.","explanation_ar":"عمره سنة فهو صغير جدًا.","options":["old","tall","busy","young"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Which sentence about Uncle Nasser uses capitals correctly?","answer":"My uncle Nasser lives in Abha.","explanation":"Capitals for My, Nasser and Abha.","explanation_ar":"My وNasser وAbha فقط.","options":["My Uncle Nasser lives in Abha.","my uncle nasser lives in abha.","My uncle Nasser lives in Abha.","My uncle nasser Lives in Abha."],"dok":1,"skill":"conventions","_part":"Part D – Check the sentences"},{"q":"Which of these words is the name of one person?","answer":"Lama","explanation":"Lama is the name of one girl.","explanation_ar":"لمى اسم خاص.","options":["sister","kitchen","Lama","garden"],"dok":1,"skill":"special names","_part":"Part D – Check the sentences"},{"q":"In a note, which part comes first?","answer":"Dear Hessa,","explanation":"A note starts with the greeting.","explanation_ar":"الرسالة تبدأ بالتحية.","options":["With love,","Dear Hessa,","Your friend Reem","Thank you for the gift."],"dok":2,"skill":"letter parts","_part":"Part D – Check the sentences"},{"q":"A picture shows a man watering plants. What is a good prediction?","answer":"The story is about a garden.","explanation":"Watering plants happens in a garden.","explanation_ar":"السقي يكون في الحديقة.","options":["The story is about a school bus.","The story is about the moon.","The story is about a kitchen.","The story is about a garden."],"dok":2,"skill":"predict","_part":"Part D – Check the sentences"},{"q":"Which sentence is the best way to end a family page?","answer":"I love my family very much.","explanation":"A feeling sentence ends the page.","explanation_ar":"جملة المشاعر للنهاية.","options":["I love my family very much.","This is my family.","My cousin is Sultan.","There are four people in my family."],"dok":2,"skill":"order","_part":"Part D – Check the sentences"}],"unit_writing":{"task":"Write 3–4 sentences about your home. Who lives there? Which room do you like? Use capital letters and periods.","model":"This is my home in Taif. My mother, my father and my brother Ali live here. I like the kitchen. My home is a happy place.","marks":20}});
